func solve(n int, k int, x int, s string) {
	var res []rune
	x--
	for i := n - 1; i >= 0; i-- {
		if s[i] == 'a' {
			res = append(res, 'a')
		} else {
			count := 1
			for i-count >= 0 && s[i] == s[i-count] {
				count++
			}
			base := count*k + 1
			for j := 0; j < x%base; j++ {
				res = append(res, 'b')
			}
			x /= base
			i -= count - 1
		}
	}
	for i, j := 0, len(res)-1; i < j; i, j = i+1, j-1 {
		res[i], res[j] = res[j], res[i]
	}
	fmt.Println(string(res))
}

