			int[] ar = new int[n];
			for(int i=0; i<n; i++) {
				ar[i] = Integer.parseInt(sa[i]);
			}

			int ans = Integer.MAX_VALUE;
			for(int j = 0; j<3; j++) {
				for(int k = 0; k<3; k++) {
					int[][] mod3 = new int[10][2];
					for(int i=0; i<=j; i++) {
						for(int m = 0; m <=k ; m++) {
							int sum = i + m*2;
							if(sum < 10) {
								mod3[sum][0] = 1;
								mod3[sum][1] = Math.min(i+m, mod3[sum][1]);
							}
						}
					}

//					for(int i=0; i<mod3.length;i++) {
//						System.out.print(Arrays.toString(mod3[i]) + " ");
