import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int[][] p = new int[n][2];
        int[][] r = new int[n][n];
        int[] q = new int[n];
        int ans = 0;
        int cnt = 0;

        for (int i = 0; i < n; i++) {
            p[i][0] = scanner.nextInt();
            p[i][1] = scanner.nextInt();
        }

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int gcd = computeGCD(Math.abs(p[i][0] - p[j][0]), Math.abs(p[i][1] - p[j][1]));
                if (gcd % 4 == 0) {
                    cnt++;
                    r[i][j] = 1;
                    q[i]++;
                    ans += n - 2;
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 1; j < n; j++) {
                if (r[i][j] == 1) {
                    ans -= q[j] * 2;
                }
            }
        }

        System.out.println(ans);
    }

    private static int computeGCD(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}

