class Program
{
    public static void Solve(int n, int k, long x, string s)
    {
        var res = new List<char>();
        x--;
        for (int i = n - 1; i >= 0; i--)
        {
            if (s[i] == 'a')
            {
                res.Add('a');
            }
            else
            {
                int count = 1;
                while (i - count >= 0 && s[i] == s[i - count])
                {
                    count++;
                }
                long baseValue = count * k + 1;
                for (int j = 0; j < x % baseValue; j++)
                {
                    res.Add('b');
                }
                x /= baseValue;
                i = i - count + 1;
            }
        }
        res.Reverse();
        Console.WriteLine(new string(res.ToArray()));
    }

    static void Main()
    {
        var reader = new System.IO.StreamReader(Console.OpenStandardInput());
