class Program
{
    static void Main()
    {
        var reader = new System.IO.StreamReader(Console.OpenStandardInput());
        int t = int.Parse(reader.ReadLine());

        for (int i = 0; i < t; i++)
        {
            int n = int.Parse(reader.ReadLine());
            string[] input = reader.ReadLine().Split(' ');
            List<int> ar = new List<int>();
            foreach (var item in input)
            {
                ar.Add(int.Parse(item));
            }

            SolveCase(n, ar);
        }
    }

    static void SolveCase(int n, List<int> ar)
    {
        int ans = int.MaxValue;
        for (int j = 0; j < 3; j++)
        {
            for (int k = 0; k < 3; k++)
            {
                int[,] mod3 = new int[10, 2];
                for (int l = 0; l < 10; l++)
                {
                    mod3[l, 0] = 0;
                    mod3[l, 1] = int.MaxValue;
                }
                mod3[0, 0] = 1;
                mod3[0, 1] = 0;

                for (int l = 0; l <= j; l++)
                {
                    for (int m = 0; m <= k; m++)
                    {
                        int sum = l + m * 2;
                        if (sum < 10)
                        {
                            mod3[sum, 0] = 1;
                            mod3[sum, 1] = Math.Min(l + m, mod3[sum, 1]);
                        }
                    }
                }

                int mx = 0;
                foreach (int num in ar)
                {
                    int mod = num % 3;
                    int mn = int.MaxValue;
                    for (int m = mod; m <= num && m <= 9; m += 3)
                    {
                        if (mod3[m, 0] == 1)
                        {
                            mn = Math.Min((num - m) / 3, mn);
                        }
                    }

                    mx = Math.Max(mx, mn);
                }

                if (mx != int.MaxValue)
                {
                    ans = Math.Min(ans, mx + j + k);
                }
            }
        }

        Console.WriteLine(ans);
    }
}

