const MAXN: usize = 100_005;

fn solve(input: &mut dyn Iterator<Item = i32>, n: i32, m: i32) {
    static mut TAG: [i32; MAXN] = [0; MAXN];
    static mut TIM: i32 = 0;
    unsafe {
        TIM += 1;
        for _ in 0..m {
            let _a = input.next().unwrap();
            let b = input.next().unwrap() as usize;
            let _c = input.next().unwrap();
            TAG[b] = TIM;
        }
        for i in 1..=n {
            if TAG[i as usize] != TIM {
                for j in 1..=n {
                    if i != j {
                        println!("{} {}", i, j);
                    }
                }
                break;
            }
        }
    }
}

fn main() {
    use std::io::{self, BufRead};
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    let t: i32 = lines.next().unwrap().unwrap().trim().parse().unwrap();

    for _ in 0..t {
        let line = lines.next().unwrap().unwrap();
        let mut parts = line.split_whitespace();
        let n: i32 = parts.next().unwrap().parse().unwrap();
        let m: i32 = parts.next().unwrap().parse().unwrap();

        let input: Vec<i32> = lines.by_ref()
            .take_while(|_| true)
            .flat_map(|line| line.unwrap().split_whitespace())
            .map(|s| s.parse::<i32>().unwrap())
            .collect();

        solve(&mut input.into_iter(), n, m);
    }
}

