                    *ans.entry(i.pow(3)).or_insert(0) += 1;
                    *ans.entry(i.pow(2)).or_insert(0) += 1;
                } else if i.pow(2) <= j {
                    *ans.entry(i.pow(2)).or_insert(0) += 1;
                } else {
                    k.push(ans.len());
                    break;
                }
            }
            if !k.contains(&ans.len()) {
                k.push(ans.len());
            }
        }
    }

    for &i in &k {
        println!("{}", i);
    }
}

