struct CBAString;

impl CBAString {
    fn solve(n: usize, k: i32, mut x: i64, s: &str) {
        let chars: Vec<char> = s.chars().collect();
        let mut res = Vec::new();

        let mut i = n;
        while i > 0 {
            i -= 1;
            if chars[i] == 'a' {
                res.push('a');
            } else {
                let mut count = 1;
                while i >= count && chars[i] == chars[i - count] {
                    count += 1;
                }
                let base = (count * k as usize) as i64 + 1;
                for _ in 0..(x % base) {
                    res.push('b');
                }
                x /= base;
                i -= count;
            }
        }

        res.reverse();
        println!("{}", res.iter().collect::<String>());
    }

    fn main() {
        let stdin = io::stdin();
        let mut lines = stdin.lock().lines();

        let t: usize = lines.next().unwrap().expect("Failed to read line").parse().expect("Please type a number!");
        for _ in 0..t {
            let first_line = lines.next().unwrap().expect("Failed to read line");
            let parts: Vec<i32> = first_line.split_whitespace()
                .map(|s| s.parse().expect("Please type a number!"))
                .collect();
            let n = parts[0] as usize;
            let k = parts[1];
            let x = parts[2];

            let second_line = lines.next().unwrap().expect("Failed to read line");
            Self::solve(n, k, x.into(), &second_line);
        }
    }
}

fn main() {
