                    }
                }

                var mx = 0

                for l in 0..<n {
                    let mod = ar[l] % 3
                    var mn = Int.max

                    for m in stride(from: mod, through: min(ar[l], 9), by: 3) {
                        if mod3[m][0] == 1 {
                            mn = min((ar[l] - m) / 3, mn)
                        }
                    }

                    mx = max(mx, mn)
                }

                if mx != Int.max {
                    ans = min(ans, mx + j + k)
                }
            }
        }

