def egcd(a, b):
    if a == 0:
        return b, 0, 1
    g, y, x = egcd(b % a, a)
    return g, x - (b // a) * y, y

def modinv(a, m):
    g, x, _ = egcd(a, m)
    if g != 1:
        raise ValueError("modular inverse does not exist")
    return (x % m + m) % m

def choose(n, k, p):
    if k == 0 or n < k:
        return 1
    x = 1
    for i in range(k):
        x = x * (n - i) % p
        d = i + 1
        x = x * modinv(d, p) % p
    return x

