class FastIO {
    private buffer: string = '';
    private index: number = 0;
    private reader: NodeJS.ReadStream;
    private writer: NodeJS.WriteStream;

    constructor() {
        this.reader = process.stdin;
        this.writer = process.stdout;
        this.setupReader();
    }

    private setupReader(): void {
        this.reader.on('data', (chunk) => {
            this.buffer += chunk.toString();
        });
    }

    public read(): string {
        return this.buffer.trim();
    }

    public readline(): string {
        let line = '';
        while (this.index < this.buffer.length && this.buffer[this.index] !== '\n') {
            line += this.buffer[this.index++];
        }
        if (this.index < this.buffer.length) {
            this.index++; // Skip the newline character
        }
        return line;
    }

    public write(s: string): void {
        this.writer.write(s);
    }

    public flush(): void {
        this.writer.flush();
    }
}

