const MOD = 998244353;

function egcd(a: number, b: number): [number, number, number] {
    if (a === 0) {
        return [b, 0, 1];
    }
    const [g, y, x] = egcd(b % a, a);
    return [g, x - Math.floor(b / a) * y, y];
}

function modinv(a: number, m: number): number {
    const [g, x] = egcd(a, m);
    if (g !== 1) {
        throw new Error("modular inverse does not exist");
    }
    return ((x % m) + m) % m;
}

function choose(n: number, k: number, p: number): number {
    if (k === 0 || n < k) {
        return 1;
    }
    let x = 1;
    for (let i = 0; i < k; i++) {
        x = (x * (n - i)) % p;
        const d = i + 1;
        x = (x * modinv(d, p)) % p;
    }
    return x;
}

function pow(base: number, exp: number, mod: number): number {
    let result = 1;
    while (exp > 0) {
        if (exp & 1) {
            result = (result * base) % mod;
        }
        exp >>= 1;
        base = (base * base) % mod;
    }
    return result;
}

