class Scanner {
    private buffer: string[] = [];
    private currentLine: string | null = null;

    constructor() {
        rl.on('line', (line) => {
            this.currentLine = line;
            rl.pause();
        });
    }

    async next(): Promise<string> {
        if (this.buffer.length === 0) {
            return new Promise((resolve) => {
                rl.once('pause', () => {
                    this.buffer = this.currentLine!.split(/\s+/);
                    resolve(this.buffer.shift()!);
                });
            });
        } else {
            return Promise.resolve(this.buffer.shift()!);
        }
    }

    async nextInt(): Promise<number> {
        return parseInt(await this.next(), 10);
    }

    async nextLong(): Promise<number> {
        return parseFloat(await this.next());
    }

    async nextDouble(): Promise<number> {
        return parseFloat(await this.next());
    }

    async readArray(n: number): Promise<number[]> {
        const a: number[] = [];
        for (let i = 0; i < n; i++) {
            a.push(await this.nextInt());
        }
        return a;
    }

    async nextLine(): Promise<string> {
        if (this.currentLine !== null) {
            const line = this.currentLine;
            this.currentLine = null;
            return line;
        } else {
            return new Promise((resolve) => {
                rl.once('pause', () => {
                    resolve(this.currentLine!);
                });
            });
        }
    }
}

