            next_s = next_b;
            for (let j = 0; j < m - b_t; j++) {
                process.stdout.write(`${Math.floor(n / m)} `);
                for (let play = 0; play < b_p - 1; play++) {
                    process.stdout.write(`${next_s} `);
                    next_s = next_s === n ? 1 : next_s + 1;
                }
                process.stdout.write('\n');
            }
        }
    }
    process.stdout.write('\n');
}

