import java.io.*;
import java.util.*;

public class Main {
    private static final int BUFSIZE = 8192;

    public static void main(String[] args) throws IOException {
        FastIO io = new FastIO(System.in, System.out);
        int t = inp(io);
        while (t-- > 0) {
            int n = inp(io);
            List<Integer> l = inlt(io, n);
            if (n % 2 == 0) {
                io.write("YES\n");
            } else {
                boolean flag = false;
                for (int j = 0; j < n - 1; j++) {
                    if (l.get(j) >= l.get(j + 1)) {
                        flag = true;
                        break;
                    }
                }
                if (flag) {
                    io.write("YES\n");
                } else {
                    io.write("NO\n");
                }
            }
        }
        io.flush();
    }

    private static class FastIO extends PrintWriter {
        private InputStream in;
        private byte[] buffer;
        private int bufferSize, bufferPointer;

        public FastIO(InputStream in, OutputStream out) {
            super(out);
            this.in = in;
            this.bufferSize = BUFSIZE;
            this.buffer = new byte[bufferSize];
            this.bufferPointer = bufferSize;
        }

        private int read() throws IOException {
            if (bufferPointer == bufferSize) {
                bufferPointer = 0;
                bufferSize = in.read(buffer);
            }
            if (bufferSize == -1) return -1;
            return buffer[bufferPointer++];
        }

        public String readLine() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            while ((c = read()) != -1 && c != '\n' && c != '\r') {
                sb.append((char) c);
            }
            return sb.toString();
        }

        public String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            while ((c = read()) != -1 && Character.isWhitespace(c));
            if (c == -1) return null;
            while (c != -1 && !Character.isWhitespace(c)) {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public List<Integer> nextIntList(int n) throws IOException {
            List<Integer> list = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                list.add(nextInt());
            }
            return list;
        }
    }

    private static int inp(FastIO io) throws IOException {
        return io.nextInt();
    }

    private static List<Integer> inlt(FastIO io, int n) throws IOException {
        return io.nextIntList(n);
    }
}

