public class Main {
    static long n, k, x;
    static String s;
    static List<Integer> vec = new ArrayList<>();
    static List<Integer> ans = new ArrayList<>();

    public static void input(Scanner scanner) {
        String[] parts = scanner.nextLine().split(" ");
        n = Long.parseLong(parts[0]);
        k = Long.parseLong(parts[1]);
