        vec.clear();
        ans.clear();
        int cnt = 0;
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '*') {
                cnt++;
            } else {
                vec.add((int) (cnt * k));
                cnt = 0;
            }
        }
        vec.add((int) (cnt * k));
        for (int i = vec.size() - 1; i >= 0; i--) {
            ans.add((int) (x % (vec.get(i) + 1)));
            x /= (vec.get(i) + 1);
        }
        int sr = ans.size();
        for (int i = sr; i < vec.size(); i++) {
            ans.add(0);
        }
