                    mod3[0][1] = 0;
                    for (int l = 0; l < 10; l++) {
                        mod3[l][1] = Integer.MAX_VALUE;
                    }
                    for (int l = 0; l <= j; l++) {
                        for (int m = 0; m <= k; m++) {
                            mod3[l + m * 2][0] = 1;
                            mod3[l + m * 2][1] = Math.min(l + m, mod3[l + m * 2][1]);
