import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {

    private static final int MOD = 998244353;

    public static void main(String[] args) throws IOException {
        solve();
    }

    private static void solve() throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(reader.readLine());

        boolean wbPoss = true;
        boolean bwPoss = true;
        int w = 0;
        int b = 0;
        int q = 0;
        int free = 0;
        boolean anyBadPoss = true;

        for (int i = 0; i < n; i++) {
            String s = reader.readLine();
            if (s.charAt(0) == 'B') {
                b++;
                wbPoss = false;
            } else if (s.charAt(0) == 'W') {
                w++;
                bwPoss = false;
            } else if (s.charAt(0) == '?') {
                q++;
            }
            if (s.charAt(1) == 'B') {
                b++;
                bwPoss = false;
            } else if (s.charAt(1) == 'W') {
                w++;
                wbPoss = false;
            } else if (s.charAt(1) == '?') {
                q++;
            }
            if (s.equals("??")) {
                free++;
            } else if (s.charAt(0) == s.charAt(1)) {
                anyBadPoss = false;
            }
        }

        int wNeeded = n - w;
        if (wNeeded > q || wNeeded < 0) {
            System.out.println(0);
            return;
        }

        int numBadPoss;
        if (anyBadPoss) {
            numBadPoss = pow(2, free, MOD);
            if (wbPoss) {
                numBadPoss--;
            }
            if (bwPoss) {
                numBadPoss--;
            }
        } else {
            numBadPoss = 0;
        }

        System.out.println((choose(q, wNeeded, MOD) - numBadPoss + MOD) % MOD);
    }

    private static int[] egcd(int a, int b) {
        if (a == 0) {
            return new int[]{b, 0, 1};
        }
        int[] result = egcd(b % a, a);
        int g = result[0];
        int y = result[1];
        int x = result[2];
        return new int[]{g, x - (b / a) * y, y};
    }

    private static int modinv(int a, int m) {
        int[] egcdResult = egcd(a, m);
        int g = egcdResult[0];
        int x = egcdResult[1];
        if (g != 1) {
            throw new IllegalArgumentException("modular inverse does not exist");
        }
        return (x % m + m) % m;
    }

    private static int choose(int n, int k, int p) {
        if (k == 0 || n < k) {
            return 1;
        }
        int x = 1;
        for (int i = 0; i < k; i++) {
            x = (int) ((long) x * (n - i) % p);
            int d = i + 1;
            x = (int) ((long) x * modinv(d, p) % p);
        }
        return x;
    }

    private static int pow(int base, int exp, int mod) {
        int result = 1;
        base = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            exp >>= 1;
            base = (base * base) % mod;
        }
        return result;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    private static final int BUFSIZE = 8192;

    public static void main(String[] args) throws IOException {
        FastIO io = new FastIO(System.in, System.out);
        int t = io.inp();
        while (t-- > 0) {
            int n = io.inp();
            List<Integer> l = io.inlt();
            if (!l.isEmpty()) {
                int s = l.get(0);
                for (int j = 1; j < n; j++) {
                    s &= l.get(j);
                }
                io.println(s);
            }
        }
        io.flush();
    }

    static class FastIO extends PrintWriter {
        private InputStream in;
        private byte[] buffer;
        private int bufferSize, bufferPointer;

        public FastIO(InputStream in, OutputStream out) {
            super(out);
            this.in = in;
            this.bufferSize = BUFSIZE;
            this.buffer = new byte[bufferSize];
            this.bufferPointer = bufferSize;
        }

        private int read() throws IOException {
            if (bufferPointer == bufferSize) {
                bufferPointer = 0;
                bufferSize = in.read(buffer);
            }
            if (bufferSize == -1) return -1;
            return buffer[bufferPointer++];
        }

        public String readLine() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            while ((c = read()) != -1 && c != '\n' && c != '\r') {
                sb.append((char) c);
            }
            return sb.toString();
        }

        public String readString() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            while ((c = read()) != -1 && Character.isWhitespace(c)) ;
            if (c == -1) return "";
            while ((c = read()) != -1 && !Character.isWhitespace(c)) {
                sb.append((char) c);
            }
            return sb.toString();
        }

        public int inp() throws IOException {
            int sign = 1;
            int num = 0;
            int c;
            while ((c = read()) != -1 && Character.isWhitespace(c)) ;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            do {
                num *= 10;
                num += c - '0';
            } while ((c = read()) != -1 && !Character.isWhitespace(c));
            return num * sign;
        }

        public List<Integer> inlt() throws IOException {
            List<Integer> list = new ArrayList<>();
            int c;
            while ((c = read()) != -1 && Character.isWhitespace(c)) ;
            do {
                StringBuilder sb = new StringBuilder();
                while (c != -1 && !Character.isWhitespace(c)) {
                    sb.append((char) c);
                    c = read();
                }
                list.add(Integer.parseInt(sb.toString()));
            } while ((c = read()) != -1 && Character.isWhitespace(c));
            return list;
        }

        public List<String> insr() throws IOException {
            List<String> list = new ArrayList<>();
            int c;
            while ((c = read()) != -1 && Character.isWhitespace(c)) ;
            do {
                StringBuilder sb = new StringBuilder();
                while (c != -1 && !Character.isWhitespace(c)) {
                    sb.append((char) c);
                    c = read();
                }
                list.add(sb.toString());
            } while ((c = read()) != -1 && Character.isWhitespace(c));
            return list;
        }

        public int[] invr() throws IOException {
            List<Integer> list = inlt();
            int[] arr = new int[list.size()];
            for (int i = 0; i < list.size(); i++) {
                arr[i] = list.get(i);
            }
            return arr;
        }
    }
}

