    }

    private static void solve(PrintWriter out) throws IOException {
        int n = sc.nextInt(), m = sc.nextInt(), k = sc.nextInt();

        int b_t = n % m;
        int b_p = n / m + 1;

        int next_b = 1, next_s = 1;

        if (b_t == 0) {
            for (int i = 0; i < k; i++) {
                for (int j = 0; j < m; j++) {
                    out.print(n / m + " ");
                    for (int play = 0; play < n / m; play++) {
                        out.print(next_b + " ");
                        if (next_b == n) next_b = 1;
                        else next_b++;
                    }
                    out.println();
                }
            }
        } else {
            for (int i = 0; i < k; i++) {
                for (int j = 0; j < b_t; j++) {
                    out.print(n / m + 1 + " ");
                    for (int play = 0; play < b_p; play++) {
                        out.print(next_b + " ");
                        if (next_b == n) next_b = 1;
                        else next_b++;
                    }
                    out.println();
                }
                next_s = next_b;
                for (int j = 0; j < m - b_t; j++) {
                    out.print(n / m + " ");
                    for (int play = 0; play < b_p - 1; play++) {
                        out.print(next_s + " ");
                        if (next_s == n) next_s = 1;
                        else next_s++;
                    }
                    out.println();
                }
            }
        }
        out.println();
    }

