using System;
using System.Collections.Generic;

class Program
{
    const int Mod = 998244353;

    static (int, int, int) Egcd(int a, int b)
    {
        if (a == 0)
            return (b, 0, 1);
        var (g, y, x) = Egcd(b % a, a);
        return (g, x - (b / a) * y, y);
    }

    static int Modinv(int a, int m)
    {
        var (g, x, _) = Egcd(a, m);
        if (g != 1)
            throw new InvalidOperationException("modular inverse does not exist");
        return (x % m + m) % m;
    }

    static int Choose(int n, int k, int p)
    {
        if (k == 0 || n < k)
            return 1;
        long x = 1;
        for (int i = 0; i < k; i++)
        {
            x = x * (n - i) % p;
            int d = i + 1;
            x = (int)(x * Modinv(d, p) % p);
        }
        return (int)x;
    }

    static void Solve()
    {
        var reader = Console.In;
        int n = int.Parse(reader.ReadLine());

        bool wbPoss = true;
        bool bwPoss = true;
        int w = 0;
        int b = 0;
        int q = 0;
        int free = 0;
        bool anyBadPoss = true;

        for (int i = 0; i < n; i++)
        {
            string s = reader.ReadLine();
            if (s[0] == 'B')
            {
                b++;
                wbPoss = false;
            }
            else if (s[0] == 'W')
            {
                w++;
                bwPoss = false;
            }
            else if (s[0] == '?')
                q++;

            if (s[1] == 'B')
            {
                b++;
                bwPoss = false;
            }
            else if (s[1] == 'W')
            {
                w++;
                wbPoss = false;
            }
            else if (s[1] == '?')
                q++;

            if (s == "??" || s[0] == '\0' || s[1] == '\0')
                free++;
            else if (s[0] == s[1])
                anyBadPoss = false;
        }

        int wNeeded = n - w;
        if (wNeeded > q || wNeeded < 0)
        {
            Console.WriteLine(0);
            return;
        }

        int numBadPoss;
        if (anyBadPoss)
            numBadPoss = Pow(2, free, Mod);
        else
            numBadPoss = 0;

        if (wbPoss)
            numBadPoss--;
        if (bwPoss)
            numBadPoss--;

        Console.WriteLine((Choose(q, wNeeded, Mod) - numBadPoss + Mod) % Mod);
    }

    static int Pow(int baseValue, int exp, int mod)
    {
        long result = 1;
        while (exp > 0)
        {
            if ((exp & 1) == 1)
                result = result * baseValue % mod;
            exp >>= 1;
            baseValue = baseValue * baseValue % mod;
        }
        return (int)result;
    }

    static void Main(string[] args)
    {
        Solve();
    }
}

using System;
using System.Collections.Generic;
using System.IO;

class Program
{
    const int BUFSIZE = 8192;

    class FastIO
    {
        private Stream stream;
        private byte[] buffer;
        private int bufferSize;
        private int bufferIndex;

        public FastIO(Stream stream)
        {
            this.stream = stream;
            this.buffer = new byte[BUFSIZE];
            this.bufferSize = 0;
            this.bufferIndex = 0;
        }

        private bool ReadBuffer()
        {
            bufferSize = stream.Read(buffer, 0, BUFSIZE);
            bufferIndex = 0;
            return bufferSize > 0;
        }

        public string Read()
        {
            var list = new List<byte>();
            while (true)
            {
                if (bufferIndex >= bufferSize && !ReadBuffer())
                    break;
                while (bufferIndex < bufferSize)
                {
                    byte b = buffer[bufferIndex++];
                    if (b == '\n' || b == '\r')
                        break;
                    list.Add(b);
                }
                if (bufferIndex < bufferSize || stream.CanSeek)
                    break;
            }
            return System.Text.Encoding.UTF8.GetString(list.ToArray());
        }

        public string ReadLine()
        {
            var list = new List<byte>();
            while (true)
            {
                if (bufferIndex >= bufferSize && !ReadBuffer())
                    break;
                while (bufferIndex < bufferSize)
                {
                    byte b = buffer[bufferIndex++];
                    if (b == '\n')
                        break;
                    list.Add(b);
                }
                if (bufferIndex < bufferSize || stream.CanSeek)
                    break;
            }
            return System.Text.Encoding.UTF8.GetString(list.ToArray());
        }

        public void Flush()
        {
            if (stream != Console.OpenStandardOutput())
                stream.Flush();
        }
    }

    static FastIO stdin = new FastIO(Console.OpenStandardInput());
    static FastIO stdout = new FastIO(Console.OpenStandardOutput());

    static int Inp()
    {
        return int.Parse(stdin.Read());
    }

    static string Inps()
    {
        return stdin.Read();
    }

    static List<int> Inlt()
    {
        var parts = stdin.Read().Split(' ');
        var result = new List<int>();
        foreach (var part in parts)
            result.Add(int.Parse(part));
        return result;
    }

    static List<char> Insr()
    {
        return stdin.Read().ToList();
    }

    static IEnumerable<int> Invr()
    {
        var parts = stdin.Read().Split(' ');
        foreach (var part in parts)
            yield return int.Parse(part);
    }

    static void Main(string[] args)
    {
        int t = Inp();
        for (int i = 0; i < t; i++)
        {
            int n = Inp();
            var l = Inlt();
            int s = l[0];
            for (int j = 1; j < n; j++)
                s &= l[j];
            Console.WriteLine(s);
        }
    }
}

using System;
using System.Collections.Generic;

class Program
{
    static void Main()
    {
        var reader = new System.IO.StreamReader(Console.OpenStandardInput());
        int n = int.Parse(reader.ReadLine());

        List<(int, int)> p = new List<(int, int)>();
        for (int i = 0; i < n; i++)
        {
            string[] parts = reader.ReadLine().Split();
            int x = int.Parse(parts[0]);
            int y = int.Parse(parts[1]);
            p.Add((x, y));
        }

        int ans = 0;
        int cnt = 0;
        int[,] r = new int[n, n];
        int[] q = new int[n];

        for (int i = 0; i < n; i++)
        {
            for (int j = i + 1; j < n; j++)
            {
                int dx = Math.Abs(p[i].Item1 - p[j].Item1);
                int dy = Math.Abs(p[i].Item2 - p[j].Item2);
                if (Gcd(dx, dy) % 4 == 0)
                {
                    cnt++;
                    r[i, j] = 1;
                    q[i]++;
                    ans += n - 2;
                }
            }
        }

        for (int i = 0; i < n; i++)
        {
            for (int j = 1; j < n; j++)
            {
                if (r[i, j] == 1)
                {
                    ans -= q[j] * 2;
                }
            }
        }

        Console.WriteLine(ans);
    }

    static int Gcd(int a, int b)
    {
        while (b != 0)
        {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}

using System;
using System.IO;

class Program
{
    private static int N;
    private static Scanner sc;
    private static StreamWriter outStream = new StreamWriter(Console.OpenStandardOutput());

    static void Main(string[] args)
    {
        sc = new Scanner(Console.OpenStandardInput());
        N = sc.NextInt();
        while (N > 0)
        {
            Solve();
            N--;
        }
        outStream.Flush();
    }

    private static void Solve()
    {
        int n = sc.NextInt();
        int m = sc.NextInt();
        int k = sc.NextInt();

        int b_t = n % m;
        int b_p = n / m + 1;
        int next_b = 1;
        int next_s = 1;

        if (b_t == 0)
        {
            for (int i = 0; i < k; i++)
            {
                for (int j = 0; j < m; j++)
                {
                    outStream.Write((n / m) + " ");
                    for (int play = 0; play < n / m; play++)
                    {
                        outStream.Write(next_b + " ");
                        if (next_b == n)
                            next_b = 1;
                        else
                            next_b++;
                    }
                    outStream.WriteLine();
                }
            }
        }
        else
        {
            for (int i = 0; i < k; i++)
            {
                for (int j = 0; j < b_t; j++)
                {
                    outStream.Write((n / m + 1) + " ");
                    for (int play = 0; play < b_p; play++)
                    {
                        outStream.Write(next_b + " ");
                        if (next_b == n)
                            next_b = 1;
                        else
                            next_b++;
                    }
                    outStream.WriteLine();
                }
                next_s = next_b;
                for (int j = 0; j < m - b_t; j++)
                {
                    outStream.Write((n / m) + " ");
                    for (int play = 0; play < b_p - 1; play++)
                    {
                        outStream.Write(next_s + " ");
                        if (next_s == n)
                            next_s = 1;
                        else
                            next_s++;
                    }
                    outStream.WriteLine();
                }
            }
        }
        outStream.WriteLine();
    }

    public class Scanner
    {
        private readonly StreamReader reader;
        private string[] tokens;
        private int tokenIndex;

        public Scanner(Stream stream)
        {
            reader = new StreamReader(stream);
            tokens = new string[0];
            tokenIndex = 0;
        }

        private void ReadNextLine()
        {
            string line = reader.ReadLine();
            if (line != null)
            {
                tokens = line.Split(' ');
                tokenIndex = 0;
            }
        }

        public string Next()
        {
            if (tokenIndex >= tokens.Length)
            {
                ReadNextLine();
            }
            return tokens[tokenIndex++];
        }

        public int NextInt()
        {
            return int.Parse(Next());
        }

        public long NextLong()
        {
            return long.Parse(Next());
        }

        public double NextDouble()
        {
            return double.Parse(Next());
        }

        public int[] ReadArray(int n)
        {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = NextInt();
            return a;
        }

        public string NextLine()
        {
            if (tokenIndex >= tokens.Length)
            {
                return reader.ReadLine();
            }
            else
            {
                string line = tokens[tokenIndex++];
                while (tokenIndex < tokens.Length)
                {
                    line += " " + tokens[tokenIndex++];
                }
                return line;
            }
        }
    }
}

