const MAX_N: usize = 2022;

fn go(ans: &mut Vec<usize>, pos: usize, a: &mut [i64; MAX_N]) {
    ans.push(pos);
    for i in 1..=pos / 2 {
        a.swap(i, pos - i + 1);
    }
}

fn solve(input: &mut dyn BufRead) -> io::Result<()> {
    let mut buffer = String::new();
    input.read_line(&mut buffer)?;
    let n: usize = buffer.trim().parse().map_err(|_| io::Error::new(io::ErrorKind::Other, "Parse error"))?;

    let mut a = [0; MAX_N];
    buffer.clear();
    input.read_line(&mut buffer)?;
    let numbers: Vec<i64> = buffer.trim().split_whitespace()
        .map(|s| s.parse().map_err(|_| io::Error::new(io::ErrorKind::Other, "Parse error")))
        .collect::<Result<_, _>>()?;
    for (i, &num) in numbers.iter().enumerate() {
        a[i + 1] = num;
    }

    let mut ans = Vec::new();
    for i in 1..=n {
        if i % 2 != a[i] as usize % 2 {
            print!("-1\n");
            return Ok(());
        }
    }
    for i in (2..=n).rev().step_by(2) {
        for j in 1..=n {
            if a[j] == i as i64 {
                let pos = j;
                go(&mut ans, pos, &mut a);
                break;
            }
        }
        for j in 1..=n {
            if a[j] == (i - 1) as i64 {
                let pos = j - 1;
                go(&mut ans, pos, &mut a);
                break;
            }
        }
        for j in 1..=n {
            if a[j] == (i - 1) as i64 {
                let pos = j + 1;
                go(&mut ans, pos, &mut a);
                break;
            }
        }
        let pos = 3;
        go(&mut ans, pos, &mut a);
        let pos = i;
        go(&mut ans, pos, &mut a);
    }
    print!("{}\n", ans.len());
    for &v in &ans {
        print!("{} ", v);
    }
    println!();
    Ok(())
}

