}

impl FastIO {
    fn new() -> Self {
        FastIO {
            reader: io::BufReader::with_capacity(BUFSIZE, io::stdin()),
            writer: io::BufWriter::with_capacity(BUFSIZE, io::stdout()),
        }
    }

    fn read(&mut self) -> String {
        let mut buffer = String::new();
        while self.reader.read_line(&mut buffer).unwrap() > 0 {}
        buffer
    }

    fn readline(&mut self) -> String {
        let mut line = String::new();
        self.reader.read_line(&mut line).unwrap();
        line.trim_end().to_string()
    }

    fn write(&mut self, s: &str) {
        writeln!(self.writer, "{}", s).unwrap();
    }
}

