    }
    for &v in vec.iter().rev() {
        ans.push((x % (v + 1)) as usize);
        x /= v + 1;
    }
    let sr = ans.len();
    for _ in sr..vec.len() {
        ans.push(0);
    }
    let mut fin = String::new();
    for &a in ans.iter().rev() {
        fin.push_str(&"b".repeat(a));
        if !fin.is_empty() && fin.len() != s.len() {
