    let n: i64 = lines.next().unwrap().unwrap().parse().unwrap();

    let mut wb_poss = true;
    let mut bw_poss = true;
    let mut w = 0;
    let mut b = 0;
    let mut q = 0;
    let mut free = 0;
    let mut any_bad_poss = true;

    for _ in 0..n {
        let s = lines.next().unwrap().unwrap();
        if s.chars().nth(0) == Some('B') {
            b += 1;
            wb_poss = false;
        } else if s.chars().nth(0) == Some('W') {
            w += 1;
            bw_poss = false;
        } else if s.chars().nth(0) == Some('?') {
            q += 1;
        }
        if s.chars().nth(1) == Some('B') {
            b += 1;
            bw_poss = false;
        } else if s.chars().nth(1) == Some('W') {
            w += 1;
            bw_poss = false;
        } else if s.chars().nth(1) == Some('?') {
            q += 1;
        }
        if s == "??" {
            free += 1;
        } else if s.chars().nth(0) == s.chars().nth(1) {
            any_bad_poss = false;
        }
    }

    let w_needed = n - b;
    if w_needed > q || w_needed < 0 {
