    }

    let num_bad_poss = if any_bad_poss {
        let mut num = pow(2, free, MOD);
        if wb_poss {
            num -= 1;
        }
        if bw_poss {
            num -= 1;
        }
        if num < 0 {
            num += MOD;
        }
        num
    } else {
