use std::io::{self, Read, Write};

const BUFSIZE: usize = 8192;

struct FastIO {
    buffer: Vec<u8>,
    pos: usize,
    end: usize,
}

impl FastIO {
    fn new() -> Self {
        let mut buffer = vec![0; BUFSIZE];
        let stdin = io::stdin();
        let mut handle = stdin.lock();
        let end = handle.read(&mut buffer).unwrap_or(0);
        FastIO { buffer, pos: 0, end }
    }

    fn read_until(&mut self, byte: u8) -> String {
        let mut result = String::new();
        loop {
            if self.pos >= self.end {
                let stdin = io::stdin();
                let mut handle = stdin.lock();
                self.end = handle.read(&mut self.buffer).unwrap_or(0);
                self.pos = 0;
                if self.end == 0 {
                    break;
                }
            }
            while self.pos < self.end && self.buffer[self.pos] != byte {
                result.push(self.buffer[self.pos] as char);
                self.pos += 1;
            }
            if self.pos < self.end {
                result.push(self.buffer[self.pos] as char);
                self.pos += 1;
                break;
            }
        }
        result
    }

    fn read_line(&mut self) -> String {
        self.read_until(b'\n')
    }

    fn read_all(&mut self) -> String {
        let mut result = String::new();
        while self.pos < self.end || self.fill_buffer() > 0 {
            result.push_str(std::str::from_utf8(&self.buffer[self.pos..self.end]).unwrap());
            self.pos = self.end;
        }
        result
    }

    fn fill_buffer(&mut self) -> usize {
        let stdin = io::stdin();
        let mut handle = stdin.lock();
        self.end = handle.read(&mut self.buffer).unwrap_or(0);
        self.pos = 0;
        self.end
    }
}

fn inp(fast_io: &mut FastIO) -> i32 {
    fast_io.read_line().trim().parse().unwrap()
}

fn inps(fast_io: &mut FastIO) -> String {
    fast_io.read_line().trim().to_string()
}

fn inlt(fast_io: &mut FastIO) -> Vec<i32> {
    fast_io.read_line().split_whitespace().map(|x| x.parse().unwrap()).collect()
}

fn insr(fast_io: &mut FastIO) -> Vec<char> {
    fast_io.read_line().trim().chars().collect()
}

fn invr(fast_io: &mut FastIO) -> Vec<i32> {
    fast_io.read_line().split_whitespace().map(|x| x.parse().unwrap()).collect()
}

