struct Scanner<R> {
    reader: R,
    buffer: String,
}

impl<R: BufRead> Scanner<R> {
    fn new(reader: R) -> Self {
        Scanner {
            reader,
            buffer: String::new(),
        }
    }

    fn next(&mut self) -> Option<String> {
        if let Some(pos) = self.buffer.find(' ') {
            let token = self.buffer[..pos].to_string();
            self.buffer = self.buffer[pos + 1..].to_string();
            Some(token)
        } else {
            self.reader.read_line(&mut self.buffer).unwrap();
            self.buffer.pop(); // Remove newline
            if self.buffer.is_empty() {
                None
            } else {
                let token = self.buffer.clone();
                self.buffer.clear();
                Some(token)
            }
        }
    }

    fn next_int(&mut self) -> i32 {
        self.next().unwrap().parse().unwrap()
    }
}

