const int BUFSIZE = 8192;

class FastIO {
private:
    std::istream& reader;
    std::ostream& writer;
    char buffer[BUFSIZE];
    size_t bufferSize;

public:
    FastIO(std::istream& in, std::ostream& out) : reader(in), writer(out), bufferSize(0) {}

    std::string read() {
        std::ostringstream oss;
        while (true) {
            if (bufferSize == 0) {
                reader.read(buffer, BUFSIZE);
                bufferSize = reader.gcount();
                if (bufferSize == 0) break;
            }
            size_t newlinePos = std::find(buffer, buffer + bufferSize, '\n') - buffer;
            if (newlinePos < bufferSize) {
                oss.write(buffer, newlinePos + 1);
                std::copy(buffer + newlinePos + 1, buffer + bufferSize, buffer);
                bufferSize -= newlinePos + 1;
                break;
            } else {
                oss.write(buffer, bufferSize);
                bufferSize = 0;
            }
        }
        return oss.str();
    }

    std::string readLine() {
        std::string line;
        std::getline(reader, line);
        return line;
    }

    void write(const std::string& s) {
        writer << s;
    }

    void flush() {
        writer.flush();
    }
};

