                for (int l = 0; l < 10; ++l) {
                    mod3[l] = {0, INT_MAX};
                }
                for (int l = 0; l <= j; ++l) {
                    for (int m = 0; m <= k; ++m) {
                        mod3[l + m * 2] = {1, std::min(l + m, mod3[l + m * 2].second)};
