const int mod = 998244353;

std::tuple<int, int, int> egcd(int a, int b) {
    if (a == 0) {
        return {b, 0, 1};
    }
    auto [g, y, x] = egcd(b % a, a);
    return {g, x - (b / a) * y, y};
}

int modinv(int a, int m) {
    auto [g, x, _] = egcd(a, m);
    if (g != 1) {
        throw std::runtime_error("modular inverse does not exist");
    }
    return (x % m + m) % m;
}

int choose(int n, int k, int p) {
    if (k == 0 || n < k) {
        return 1;
    }
    long long x = 1;
    for (int i = 0; i < k; ++i) {
        x = x * (n - i) % p;
        int d = i + 1;
        x = x * modinv(d, p) % p;
    }
    return static_cast<int>(x);
}

void solve() {
    int n;
    std::cin >> n;

    bool wb_poss = true;
    bool bw_poss = true;
    int w = 0;
    int b = 0;
    int q = 0;
    int free = 0;
    bool any_bad_poss = true;

    for (int i = 0; i < n; ++i) {
        std::string s;
        std::cin >> s;
        if (s[0] == 'B') {
            b++;
            wb_poss = false;
        } else if (s[0] == 'W') {
            w++;
            bw_poss = false;
        } else if (s[0] == '?') {
            q++;
        }
        if (s[1] == 'B') {
            b++;
            bw_poss = false;
        } else if (s[1] == 'W') {
            w++;
            wb_poss = false;
        } else if (s[1] == '?') {
            q++;
        }
        if (s == "??" ) {
            free++;
        } else if (s[0] == s[1]) {
            any_bad_poss = false;
        }
    }

    int w_needed = n - w;
    if (w_needed > q || w_needed < 0) {
        std::cout << 0 << std::endl;
        return;
    }

    int num_bad_poss;
    if (any_bad_poss) {
        long long num_free_combinations = 1LL << free;
        num_bad_poss = static_cast<int>(num_free_combinations % mod);
        if (wb_poss) {
            num_bad_poss--;
        }
        if (bw_poss) {
            num_bad_poss--;
        }
    } else {
        num_bad_poss = 0;
    }

    std::cout << (choose(q, w_needed, mod) - num_bad_poss + mod) % mod << std::endl;
}

