const int BUFSIZE = 8192;

class FastIO {
public:
    FILE* fd;
    char buffer[BUFSIZE];
    bool writable;

    FastIO(FILE* _fd, bool _writable) : fd(_fd), writable(_writable) {}

    std::string read() {
        std::string result;
        size_t bytesRead;
        do {
            bytesRead = fread(buffer, 1, BUFSIZE, fd);
            if (bytesRead > 0) {
                result.append(buffer, bytesRead);
            }
        } while (bytesRead == BUFSIZE);
        return result;
    }

    std::string readLine() {
        std::string result;
        size_t bytesRead;
        do {
            bytesRead = fread(buffer, 1, BUFSIZE, fd);
            if (bytesRead > 0) {
                result.append(buffer, bytesRead);
                if (result.find('\n') != std::string::npos) {
                    break;
                }
            }
        } while (bytesRead == BUFSIZE);
        size_t newlinePos = result.find('\n');
        return newlinePos != std::string::npos ? result.substr(0, newlinePos) : result;
    }

    void flush() {
        if (writable) {
            fwrite(buffer, 1, sizeof(buffer), stdout);
        }
    }
};

class IOWrapper {
public:
    FastIO* fastIO;
    bool writable;

    IOWrapper(FastIO* _fastIO, bool _writable) : fastIO(_fastIO), writable(_writable) {}

    std::string read() {
        return fastIO->readLine();
    }

    std::string readLine() {
        return fastIO->readLine();
    }

    void flush() {
        if (writable) {
            fflush(stdout);
        }
    }
};

