class Scanner {
private:
    std::istream& input;
    std::istringstream buffer;
    std::string currentLine;
    bool hasBufferedLine;

public:
    Scanner(std::istream& in) : input(in), hasBufferedLine(false) {}

    std::string next() {
        if (hasBufferedLine && !buffer.eof()) {
            std::string token;
            buffer >> token;
            return token;
        }
        if (!std::getline(input, currentLine)) {
            throw std::runtime_error("No more input");
        }
        hasBufferedLine = true;
        buffer.clear();
        buffer.str(currentLine);
        std::string token;
        buffer >> token;
        return token;
    }

    int nextInt() {
        return std::stoi(next());
    }

    long long nextLong() {
        return std::stoll(next());
    }

    double nextDouble() {
        return std::stod(next());
    }

    std::vector<int> readArray(int n) {
        std::vector<int> array(n);
        for (int i = 0; i < n; ++i) {
            array[i] = nextInt();
        }
        return array;
    }

    std::string nextLine() {
        if (hasBufferedLine && !buffer.eof()) {
            std::getline(buffer, currentLine);
            hasBufferedLine = false;
            return currentLine;
        }
        if (!std::getline(input, currentLine)) {
            throw std::runtime_error("No more input");
        }
        return currentLine;
    }
};

