class FastIO {
    private let fileHandle: FileHandle
    private var buffer: Data

    init(fileHandle: FileHandle) {
        self.fileHandle = fileHandle
        self.buffer = Data()
    }

    func read() -> String {
        while true {
            let data = fileHandle.availableData
            if data.isEmpty {
                break
            }
            buffer.append(data)
        }
        return String(data: buffer, encoding: .utf8) ?? ""
    }

    func readline() -> String? {
        repeat {
            if let range = buffer.range(of: "\n".data(using: .utf8)!, options: [], in: buffer.startIndex..<buffer.endIndex) {
                let line = String(data: buffer.subdata(in: buffer.startIndex..<range.upperBound), encoding: .utf8)
                buffer.removeSubrange(buffer.startIndex..<range.upperBound)
                return line?.trimmingCharacters(in: .whitespacesAndNewlines)
            }
        } while fileHandle.readData(ofLength: 1).count > 0
        return nil
    }

    func write(_ string: String) {
        if let data = string.data(using: .utf8) {
            fileHandle.write(data)
        }
    }

    func flush() {
        fileHandle.synchronizeFile()
    }
}

