let mod = 998244353

func egcd(_ a: Int, _ b: Int) -> (Int, Int, Int) {
    if a == 0 {
        return (b, 0, 1)
    }
    let (g, y, x) = egcd(b % a, a)
    return (g, x - (b / a) * y, y)
}

func modinv(_ a: Int, _ m: Int) -> Int {
    let (_, x, _) = egcd(a, m)
    return ((x % m + m) % m)
}

func choose(_ n: Int, _ k: Int, _ p: Int) -> Int {
    if k == 0 || n < k {
        return 1
    }
    var x = 1
    for i in 0..<k {
        x = (x * (n - i)) % p
        let d = i + 1
        x = (x * modinv(d, p)) % p
    }
    return x
}

