func pow(_ base: Int, _ exp: Int, _ mod: Int) -> Int {
    var result = 1
    var base = base
    var exp = exp
    while exp > 0 {
        if exp & 1 == 1 {
            result = (result * base) % mod
        }
        exp >>= 1
        base = (base * base) % mod
    }
    return result
}

