class IOWrapper {
    private var buffer: Data
    private let writable: Bool

    init(fileDescriptor: Int32) {
        self.buffer = Data()
        self.writable = fileDescriptor != STDIN_FILENO
    }

    func read() -> String {
        let line = readLine()
        return line.trimmingCharacters(in: .whitespacesAndNewlines)
    }

    func readLine() -> String {
        guard let newlineIndex = String(data: buffer, encoding: .utf8)?.firstIndex(of: "\n") else {
            let newChunk = FileHandle(fileDescriptor: STDIN_FILENO).readData(ofLength: BUFSIZE)
            buffer.append(newChunk)
            return readLine()
        }
        let line = String(data: buffer.prefix(upTo: newlineIndex.utf16Offset(in: String(data: buffer, encoding: .utf8) ?? "")), encoding: .utf8) ?? ""
        buffer.removeSubrange(...newlineIndex.utf16Offset(in: String(data: buffer, encoding: .utf8) ?? ""))
        return line
    }

    func flush() {
        if writable {
            FileHandle(fileDescriptor: STDOUT_FILENO).write(buffer)
            buffer.removeAll()
        }
    }
}

