    init() {
        let input = readLine() ?? ""
        self.buffer = input.split(separator: " ").map { String($0) }
    }

    func next() -> String {
        if !buffer.isEmpty {
            return buffer.removeFirst()
        } else {
            let input = readLine() ?? ""
            self.buffer = input.split(separator: " ").map { String($0) }
            return buffer.removeFirst()
        }
    }

    func nextInt() -> Int {
        return Int(next())!
    }

    func nextLong() -> Int64 {
        return Int64(next())!
    }

    func nextDouble() -> Double {
        return Double(next())!
    }

    func readArray(_ n: Int) -> [Int] {
        return (0..<n).map { _ in nextInt() }
    }

    func nextLine() -> String {
        if !buffer.isEmpty {
            return buffer.joined(separator: " ")
        } else {
            return readLine() ?? ""
        }
    }
}

