class FastReader:
    def __init__(self):
        self.buffer = sys.stdin.read().split()
        self.index = 0

    def next(self):
        token = self.buffer[self.index]
        self.index += 1
        return token

    def next_int(self):
        return int(self.next())

    def next_long(self):
        return int(self.next())

    def next_double(self):
        return float(self.next())

    def next_line(self):
        start_index = self.index
        while self.index < len(self.buffer) and self.buffer[self.index] != '\n':
            self.index += 1
        line = ' '.join(self.buffer[start_index:self.index])
        if self.index < len(self.buffer) and self.buffer[self.index] == '\n':
            self.index += 1
        return line

def reverse(arr, r):
