class FastIO:
    def __init__(self, stream):
        self.stream = stream
        self.buffer = bytearray()
        self.writable = stream.writable()

    def read(self):
        while True:
            try:
                data = self.stream.read(8192)
                if not data:
                    break
                self.buffer.extend(data)
            except Exception:
                pass
        return self.buffer.decode('ascii')

    def readline(self):
        line = bytearray()
        while True:
            try:
                char = self.stream.read(1)
                if not char or char == b'\n':
                    break
                line.append(ord(char[0]))
            except Exception:
                pass
        return line.decode('ascii').rstrip('\n')

    def write(self, text):
        self.stream.write(text.encode('ascii'))

    def flush(self):
        self.stream.flush()

