import sys

class FastIO:
    def __init__(self, file):
        self.file = file
        self._buffer = bytearray()
        self._eof = False

    def read(self, n=-1):
        if self._eof:
            return b''
        if n == -1:
            data = self.file.read()
            self._eof = True
            return data
        else:
            while len(self._buffer) < n and not self._eof:
                chunk = self.file.read(8192)
                if not chunk:
                    self._eof = True
                self._buffer.extend(chunk)
            data = self._buffer[:n]
            self._buffer = self._buffer[n:]
            return data

    def readline(self):
        if self._eof:
            return b''
        line = bytearray()
        while True:
            if b'\n' in self._buffer:
                newline_pos = self._buffer.index(b'\n')
                line.extend(self._buffer[:newline_pos + 1])
                self._buffer = self._buffer[newline_pos + 1:]
                break
            else:
                chunk = self.file.read(8192)
                if not chunk:
                    self._eof = True
                if not chunk and len(line) == 0:
                    return b''
                line.extend(chunk)
        return bytes(line)

    def write(self, data):
        self.file.buffer.write(data)

    def flush(self):
        self.file.flush()

