MOD = 998244353

def egcd(a, b):
    if a == 0:
        return b, 0, 1
    else:
        g, y, x = egcd(b % a, a)
        return g, x - (b // a) * y, y

def modinv(a, m):
    g, x, _ = egcd(a, m)
    if g != 1:
        raise Exception("modular inverse does not exist")
    else:
        return (x % m + m) % m

def choose(n, k, p):
    if k == 0:
        return 1
    x = n
    for y in range(n - 1, n - k, -1):
        x = (x * y) % p
    d = 1
    for i in range(2, k + 1):
        d = (d * i) % p
    return (x * modinv(d, p)) % p

