    let num_bad_poss: number;
    if (any_bad_poss) {
        num_bad_poss = Number((BigInt(2) ** BigInt(free)) % BigInt(MOD)) - (bw_poss ? 1 : 0) - (wb_poss ? 1 : 0);
    } else {
        num_bad_poss = 0;
    }

    console.log((choose(q, w_needed, MOD) - num_bad_poss + MOD) % MOD);
