	fmt.Fscanf(reader, "%d\n", &T)

	for i := 0; i < T; i++ {
		var n int
		fmt.Fscanf(reader, "%d\n", &n)

		a := make([]int, n)
		flag := 0

		line, _ := reader.ReadString('\n')
		parts := strings.Fields(line)
		for j := 0; j < n; j++ {
			a[j], _ = strconv.Atoi(parts[j])
			p := j + 1
			if p%2 != a[j]%2 {
				flag = 1
			}
		}

		if flag == 1 {
			fmt.Fprintln(writer, -1)
		} else {
			var list []int

			for i := n; i > 1; i -= 2 {
				in1, in2 := 0, 0
				for j := 0; j < n; j++ {
					if a[j] == i {
						in1 = j
					} else if a[j] == i-1 {
						in2 = j
					}
				}

				reverse(a, in1)
				if in1 > in2 {
					in2 = in1 - in2
				}
				reverse(a, in2-1)
				reverse(a, in2+1)
				reverse(a, 2)
				reverse(a, i-1)

				list = append(list, in1+1)
				list = append(list, in2)
				list = append(list, in2+2)
				list = append(list, 3)
				list = append(list, i)
			}

			fmt.Fprintln(writer, len(list))
			for _, v := range list {
				fmt.Fprintf(writer, "%d ", v)
			}
			fmt.Fprintln(writer)
		}
	}
}

func reverse(a []int, r int) {
	for i := 0; i <= r/2; i++ {
		l, h := i, r-i
		a[l], a[h] = a[h], a[l]
	}
}

