type Dsu struct {
	parent []int
}

func NewDsu(n int) *Dsu {
	d := &Dsu{parent: make([]int, n+1)}
	return d
}

func (d *Dsu) MakeSet() {
	for i := 1; i < len(d.parent); i++ {
		d.parent[i] = i
	}
}

func (d *Dsu) findParent(node int) int {
	if node == d.parent[node] {
		return node
	}
	d.parent[node] = d.findParent(d.parent[node])
	return d.parent[node]
}

func (d *Dsu) union(u, v int) int {
	uParent := d.findParent(u)
	vParent := d.findParent(v)

	if uParent != vParent {
		d.parent[vParent] = uParent
		return 0
	} else {
		return -1
	}
}

func readInts(scanner *bufio.Scanner) []int {
	scanner.Scan()
	input := strings.Fields(scanner.Text())
	ints := make([]int, len(input))
	for i, s := range input {
		ints[i], _ = strconv.Atoi(s)
	}
	return ints
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	input := readInts(scanner)
	n, m1, m2 := input[0], input[1], input[2]

	d1 := NewDsu(n)
	d2 := NewDsu(n)
	d1.MakeSet()
	d2.MakeSet()

	flag := false
	for i := 0; i < m1; i++ {
		input = readInts(scanner)
		u, v := input[0], input[1]
		if d1.union(u, v) == -1 {
			flag = true
		}
	}
	for i := 0; i < m2; i++ {
		input = readInts(scanner)
		u, v := input[0], input[1]
		if d2.union(u, v) == -1 {
			flag = true
		}
	}

	if flag {
		fmt.Println(0)
		return
	}

	var result [][]int
	for i := 1; i <= n; i++ {
		for j := i + 1; j <= n; j++ {
			y := d1.findParent(j)
			y1 := d1.findParent(y)
			x := d2.findParent(j)
			x1 := d2.findParent(x)

			if d1.union(i, j) == -1 {
				d1.parent[y] = y1
			} else if d2.union(i, j) == -1 {
				d2.parent[x] = x1
				d1.parent[y] = y1
			} else {
				d1.union(i, j)
				d2.union(i, j)
				result = append(result, []int{i, j})
			}
		}
	}

	fmt.Println(len(result))
	for _, pair := range result {
		fmt.Printf("%d %d\n", pair[0], pair[1])
	}
}

