			fastIO.WriteString(fmt.Sprintf("%d\n", int64(arr[0]) * int64(arr[1])))
		} else {
			res := int64(-1)
			for i := 0; i < n-1; i++ {
				product := int64(max(arr[i+1], arr[i])) * int64(min(arr[i+1], arr[i]))
				if product > res {
					res = product
				}
			}
			fastIO.WriteString(fmt.Sprintf("%d\n", res))
		}
	}
}

