const mod = 998244353

func egcd(a, b int) (int, int, int) {
	if a == 0 {
		return b, 0, 1
	} else {
		g, y, x := egcd(b%a, a)
		return g, x - (b/a)*y, y
	}
}

func modinv(a, m int) int {
	g, x, _ := egcd(a, m)
	if g != 1 {
		panic("modular inverse does not exist")
	} else {
		return (x%m + m) % m
	}
}

func choose(n, k, p int) int {
	if k == 0 {
		return 1
	}
	x := n
	for y := n - 1; y > n-k; y-- {
		x = (x * y) % p
	}
	d := 1
	for i := 2; i <= k; i++ {
		d = (d * i) % p
	}
	return (x * modinv(d, p)) % p
}

func solve() {
	reader := bufio.NewReader(os.Stdin)
	nStr, _ := reader.ReadString('\n')
	var n int
	fmt.Sscanf(nStr, "%d", &n)

	wbPoss := n > 1
	bwPoss := n > 1
	w := 0
	b := 0
	q := 0
	free := 0
	anyBadPoss := n > 1

	for i := 0; i < n; i++ {
		s, _ := reader.ReadString('\n')
		s = s[:len(s)-1] // Remove newline character
		if s[0] == 'B' {
			b++
			wbPoss = false
		} else if s[0] == 'W' {
			w++
			bwPoss = false
		} else if s[0] == '?' {
			q++
		}

		if s[1] == 'B' {
			b++
			bwPoss = false
		} else if s[1] == 'W' {
			w++
			wbPoss = false
		} else if s[1] == '?' {
			q++
		}

		if s == "??" {
			free++
		} else if s[0] == s[1] {
			anyBadPoss = false
		}
	}

	wNeeded := n - w
	if wNeeded > q || wNeeded < 0 {
		fmt.Println(0)
		return
	}

	var numBadPoss int
	if anyBadPoss {
		numBadPoss = (powerOfTwo(free, mod) - boolToInt(bwPoss) - boolToInt(wbPoss) + mod) % mod
	} else {
		numBadPoss = 0
	}

	fmt.Println((choose(q, wNeeded, mod)-numBadPoss+mod)%mod)
}

func powerOfTwo(n, mod int) int {
	result := 1
	base := 2
	for n > 0 {
		if n%2 == 1 {
			result = (result * base) % mod
		}
		base = (base * base) % mod
		n /= 2
	}
	return result
}

func boolToInt(b bool) int {
	if b {
		return 1
	}
	return 0
}

