    public static void main(String[] args) throws IOException {
        int t = inp();
        while (t-- > 0) {
            int n = inp();
            int[] l = inlt();
            if (n % 2 == 0) {
                print("YES");
            } else {
                boolean flag = false;
                for (int j = 0; j < n - 1; j++) {
                    if (l[j] >= l[j + 1]) {
                        flag = true;
                        break;
                    }
                }
                if (flag) {
                    print("YES");
                } else {
                    print("NO");
                }
            }
        }
    }

    private static int inp() throws IOException {
        return Integer.parseInt(io.readLine());
    }

    private static String inps() throws IOException {
        return io.readLine().trim();
    }

    private static int[] inlt() throws IOException {
        String[] parts = io.readLine().split(" ");
        int[] result = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            result[i] = Integer.parseInt(parts[i]);
        }
        return result;
    }

    private static char[] insr() throws IOException {
        return io.readLine().toCharArray();
    }

    private static void print(Object... args) throws IOException {
        String sep = " ";
        String end = "\n";
        for (int i = 0; i < args.length; i++) {
            if (i != 0) io.write(sep);
            io.write(args[i].toString());
        }
        io.write(end);
    }

    static class FastIO extends PrintWriter {
        private InputStream in;
        private byte[] buffer;
        private int bufferSize, bufferPointer;

        public FastIO(InputStream in, OutputStream out) {
            super(out);
            this.in = in;
            this.bufferSize = 8192;
            this.buffer = new byte[bufferSize];
            this.bufferPointer = bufferSize;
        }

        private int read() throws IOException {
            if (bufferPointer == bufferSize) {
                bufferPointer = 0;
                bufferSize = in.read(buffer);
            }
            if (bufferSize == -1) return -1;
            return buffer[bufferPointer++];
        }

        public String readLine() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            while ((c = read()) != -1 && c != '\n' && c != '\r') {
                sb.append((char) c);
            }
            return sb.toString();
        }

        @Override
        public void close() {
            try {
                in.close();
            } catch (IOException e) {
                throw new RuntimeException(e);
            } finally {
                super.close();
            }
        }
    }
}

