                        bad = true;
                        break;
                    }
                }
                System.out.println(bad ? m / 3 + 1 : m / 3);
            } else if (x == 1) {
                boolean two = false;
                boolean one = false;
                for (int guy : a) {
                    if (guy % 3 == 2) {
                        two = true;
                    } else if (guy == 1 || guy == m - 1) {
                        one = true;
                    }
                }
                System.out.println(two && one ? m / 3 + 2 : m / 3 + 1);
            } else {
                boolean one = false;
                for (int guy : a) {
