use std::io::{self, BufRead};

struct FastReader {
    reader: io::BufReader<io::Stdin>,
    buffer: String,
    tokens: Vec<String>,
}

impl FastReader {
    fn new() -> Self {
        FastReader {
            reader: io::BufReader::new(io::stdin()),
            buffer: String::new(),
            tokens: Vec::new(),
        }
    }

    fn next_token(&mut self) -> Option<String> {
        if let Some(token) = self.tokens.pop() {
            return Some(token);
        }
        self.buffer.clear();
        if self.reader.read_line(&mut self.buffer).unwrap_or(0) == 0 {
            return None;
        }
        self.tokens = self.buffer.trim().split_whitespace().map(|s| s.to_string()).collect();
        self.next_token()
    }

    fn next_int(&mut self) -> i32 {
        self.next_token().unwrap().parse().unwrap()
    }

    fn next_long(&mut self) -> i64 {
        self.next_token().unwrap().parse().unwrap()
    }

    fn next_double(&mut self) -> f64 {
        self.next_token().unwrap().parse().unwrap()
    }

    fn next_line(&mut self) -> String {
        if let Some(token) = self.tokens.pop() {
            return token;
        }
        self.buffer.clear();
        self.reader.read_line(&mut self.buffer).unwrap_or(0);
        self.buffer.trim().to_string()
    }
}

fn reverse(arr: &mut [i32], r: usize) {
    let mut l = 0;
    while l <= r / 2 {
        arr.swap(l, r - l);
        l += 1;
    }
}

