use std::io::{self, Read, Write};

struct FastIO {
    buffer: Vec<u8>,
    read_pos: usize,
}

impl FastIO {
    fn new() -> Self {
        let mut buffer = vec![0; 8192];
        let stdin = io::stdin();
        let mut handle = stdin.lock();
        let bytes_read = handle.read(&mut buffer).unwrap();
        buffer.truncate(bytes_read);
        FastIO { buffer, read_pos: 0 }
    }

    fn read_until(&mut self, delimiter: u8) -> String {
        let mut result = String::new();
        while self.read_pos < self.buffer.len() {
            if self.buffer[self.read_pos] == delimiter {
                result.push_str(std::str::from_utf8(&self.buffer[..self.read_pos]).unwrap());
                self.read_pos += 1;
                return result;
            }
            result.push(self.buffer[self.read_pos] as char);
            self.read_pos += 1;
        }
        if !result.is_empty() {
            result
        } else {
            let mut handle = io::stdin().lock();
            let mut line = String::new();
            handle.read_line(&mut line).unwrap();
            line.pop(); // Remove newline character
            line
        }
    }

    fn read_line(&mut self) -> String {
        self.read_until(b'\n')
    }

    fn read_int(&mut self) -> i32 {
        let line = self.read_line();
        line.trim().parse().unwrap()
    }

    fn read_ints(&mut self) -> Vec<i32> {
        self.read_line()
            .split_whitespace()
            .map(|s| s.parse().unwrap())
            .collect()
    }
}

