            for j in 0..m {
                let ch = line.chars().nth(j).unwrap();
                d[i][j] = match ch {
                    'R' => -1,
                    'U' => -2,
                    'L' => -3,
                    _ => -4,
                };
            }
        }

        let mut r = 0;
        let mut pos = (0, 0);

        for i in 0..n {
            for j in 0..m {
                let (mut a, mut b) = (i, j);
                let mut p = d[i][j];
                let mut c = 0;
