                while p < 0 {
                    d[a][b] = 0;
                    st.push((a, b));
                    match p {
                        -1 => b += 1,
                        -2 => a = a.saturating_sub(1),
                        -3 => b = b.saturating_sub(1),
                        _ => a += 1,
                    }
                    c += 1;
                    if a < n && b < m {
                        p = d[a][b];
                    } else {
                        for (ii, &(x, y)) in st.iter().enumerate() {
                            d[x][y] = c - ii;
                        }
                        p = -1;
                        break;
                    }
                }

                if p == 0 {
