    let mut bw_poss = n > 1;
    let mut w = 0;
    let mut b = 0;
    let mut q = 0;
    let mut free = 0;
    let mut any_bad_poss = n > 1;

    for _ in 0..n {
        let s = lines.next().unwrap().unwrap();
        if s.chars().nth(0).unwrap() == 'B' {
            b += 1;
            wb_poss = false;
        } else if s.chars().nth(0).unwrap() == 'W' {
            w += 1;
            bw_poss = false;
        } else if s.chars().nth(0).unwrap() == '?' {
            q += 1;
        }

        if s.chars().nth(1).unwrap() == 'B' {
            b += 1;
            bw_poss = false;
        } else if s.chars().nth(1).unwrap() == 'W' {
            w += 1;
            bw_poss = false;
        } else if s.chars().nth(1).unwrap() == '?' {
            q += 1;
        }

        if s == "??".to_string() {
            free += 1;
        } else if s.chars().nth(0).unwrap() == s.chars().nth(1).unwrap() {
            any_bad_poss = false;
        }
    }

    let w_needed = n - w;
    if w_needed > q || w_needed < 0 {
        println!("0");
        return;
    }

    let num_bad_poss = if any_bad_poss {
        (2_i64.pow(free as u32) % MOD - if bw_poss { 1 } else { 0 } - if wb_poss { 1 } else { 0 } + MOD) % MOD
    } else {
        0
    };

    println!("{}", (choose(q, w_needed, MOD) - num_bad_poss + MOD) % MOD);
}

