            if (i > 0) {
                dp2[i - 1] = (dp2[i - 1] << 1) % mod;
                dp2[i - 1] = (dp2[i - 1] + dp1[i - 1]) % mod;
            }
            dp2[i + 1] = (dp2[i + 1] << 1) % mod;
        }

        long long ans = 0;
        for (int i = 0; i <= n + 1; ++i) {
            ans = (ans + dp1[i] + dp2[i]) % mod;
        }

        std::cout << (ans - 1 + mod) % mod << std::endl;
    }
    return 0;
}

