    std::string line;
    std::string token;

public:
    FastReader() {
        std::getline(std::cin, line);
        iss.str(line);
    }

    std::string next() {
        if (iss >> token) {
            return token;
        }
        std::getline(std::cin, line);
        iss.clear();
        iss.str(line);
        iss >> token;
        return token;
    }

    int nextInt() {
        return std::stoi(next());
    }

    long long nextLong() {
        return std::stoll(next());
    }

    double nextDouble() {
        return std::stod(next());
    }

    std::string nextLine() {
        if (iss >> token) {
            std::istringstream lineStream(line);
            lineStream.seekg(iss.tellg());
            std::getline(lineStream, token);
            return token;
        }
        std::getline(std::cin, line);
        return line;
    }
};

void reverse(std::vector<int>& a, int r) {
    for (int i = 0; i <= r / 2; ++i) {
        int l = i, h = r - i;
        std::swap(a[l], a[h]);
    }
}

