class FastIO {
private:
    static const int BUFSIZE = 8192;
    FILE* _inputStream;
    FILE* _outputStream;
    char _buffer[BUFSIZE];
    int _bufferSize;
    int _bufferIndex;

public:
    FastIO(FILE* inputStream, FILE* outputStream)
        : _inputStream(inputStream), _outputStream(outputStream), _bufferSize(0), _bufferIndex(0) {}

    std::string ReadLine() {
        std::ostringstream oss;
        while (true) {
            if (_bufferIndex >= _bufferSize) {
                _bufferSize = fread(_buffer, 1, BUFSIZE, _inputStream);
                _bufferIndex = 0;
            }
            if (_bufferSize == 0) break;

            int newlineIndex = -1;
            for (int i = _bufferIndex; i < _bufferSize; ++i) {
                if (_buffer[i] == '\n') {
                    newlineIndex = i;
                    break;
                }
            }

            if (newlineIndex >= 0) {
                oss.write(_buffer + _bufferIndex, newlineIndex - _bufferIndex + 1);
                _bufferIndex = newlineIndex + 1;
                break;
            } else {
                oss.write(_buffer + _bufferIndex, _bufferSize - _bufferIndex);
                _bufferIndex = _bufferSize;
            }
        }
        return oss.str();
    }

    void WriteLine(long value) {
        fprintf(_outputStream, "%ld\n", value);
    }
};

int main() {
