class FastIO {
    private let inputStream: InputStream
    private var buffer = Data()

    init(inputStream: InputStream) {
        self.inputStream = inputStream
        self.inputStream.open()
    }

    func readToEnd() -> String {
        while inputStream.hasBytesAvailable {
            var data = Data(count: 8192)
            let bytesRead = inputStream.read(into: &data)
            if bytesRead > 0 {
                buffer.append(data.subdata(in: 0..<bytesRead))
            } else {
                break
            }
        }
        return String(data: buffer, encoding: .ascii) ?? ""
    }

    func readLine() -> String? {
        while true {
            if let range = buffer.range(of: "\n".data(using: .ascii)!, options: [], in: buffer.startIndex..<buffer.endIndex) {
                let line = String(data: buffer.subdata(in: buffer.startIndex..<range.lowerBound), encoding: .ascii)
                buffer.removeSubrange(buffer.startIndex...range.upperBound)
                return line?.trimmingCharacters(in: .whitespacesAndNewlines)
            }
            var data = Data(count: 8192)
            let bytesRead = inputStream.read(into: &data)
            if bytesRead > 0 {
                buffer.append(data.subdata(in: 0..<bytesRead))
            } else {
                let line = String(data: buffer, encoding: .ascii)
                buffer.count = 0
                return line?.trimmingCharacters(in: .whitespacesAndNewlines)
            }
        }
    }

    deinit {
        inputStream.close()
    }
}

