class FastIO {
    private let bufferSize = 8192
    private var buffer: [UInt8] = Array(repeating: 0, count: 8192)
    private var bufferIndex = 0
    private var bytesRead = 0
    private let fileHandleIn: FileHandle
    private let fileHandleOut: FileHandle

    init(fileHandleIn: FileHandle = .standardInput, fileHandleOut: FileHandle = .standardOutput) {
        self.fileHandleIn = fileHandleIn
        self.fileHandleOut = fileHandleOut
    }

    func readLine() -> String? {
        var line = ""
        while true {
            if bufferIndex >= bytesRead {
                bufferIndex = 0
                let data = fileHandleIn.availableData
                bytesRead = data.count
                data.copyBytes(to: &buffer, count: bytesRead)
            }
            while bufferIndex < bytesRead && buffer[bufferIndex] != UInt8(ascii: "\n") {
                if let char = Character(UnicodeScalar(buffer[bufferIndex])) {
                    line.append(char)
                }
                bufferIndex += 1
            }
            if bufferIndex < bytesRead {
                // Found newline
                bufferIndex += 1
                break
            } else {
                // No newline in current buffer, read more
                continue
            }
        }
        return line
    }

    func write(_ string: String) {
        if let data = string.data(using: .ascii) {
            fileHandleOut.write(data)
        }
    }
}

