func egcd(_ a: Int, _ b: Int) -> (Int, Int, Int) {
    if a == 0 {
        return (b, 0, 1)
    } else {
        let (g, y, x) = egcd(b % a, a)
        return (g, x - (b / a) * y, y)
    }
}

func modinv(_ a: Int, _ m: Int) -> Int {
    let (g, x, _) = egcd(a, m)
    if g != 1 {
        fatalError("modular inverse does not exist")
    } else {
        return ((x % m + m) % m)
    }
}

func choose(_ n: Int, _ k: Int, _ p: Int) -> Int {
    if k == 0 {
        return 1
    }
    var x = BigInteger(n)
    for y in stride(from: n - 1, through: n - k + 1, by: -1) {
        x *= BigInteger(y)
        x %= BigInteger(p)
    }
    var d = BigInteger(1)
    for i in 2...k {
        d *= BigInteger(i)
        d %= BigInteger(p)
    }
    return Int((x * BigInteger(modinv(Int(d), p))) % BigInteger(p))
}

