        }

        if s == "??" {
            free += 1
        } else if s.first == s.dropFirst().first {
            anyBadPoss = false
        }
    }

    let wNeeded = n - w
    if wNeeded > q || wNeeded < 0 {
        print(0)
        return
    }

    let numBadPoss: Int
    if anyBadPoss {
        numBadPoss = (Int(pow(2.0, Double(free))) - (bwPoss ? 1 : 0) - (wbPoss ? 1 : 0)) % mod
    } else {
        numBadPoss = 0
    }

    print((choose(q, wNeeded, mod) - numBadPoss + mod) % mod)
}

