MOD = 998244353

def bin_pow(a, b):
    res = 1
    while b > 0:
        a %= MOD
        if b & 1 == 1:
            res = (res * a) % MOD
        b >>= 1
        a = (a * a) % MOD
    return res

def mod_inverse(a):
    return bin_pow(a, MOD - 2)

def mul(a, b):
    return (a * b) % MOD

def n_cr(n, r, fact, inv_fact):
    res = mul(fact[n], inv_fact[r])
    res = mul(res, inv_fact[n - r])
    return res

