const MOD: number = 998244353;

function binPow(a: number, b: number): number {
    let res: number = 1;
    while (b > 0) {
        a %= MOD;
        if (b & 1) {
            res = (res * a) % MOD;
        }
        b >>= 1;
        a = (a * a) % MOD;
    }
    return res;
}

function modInverse(a: number): number {
    return binPow(a, MOD - 2);
}

function mul(a: number, b: number): number {
    return (a * b) % MOD;
}

function nCr(n: number, r: number, fact: number[], invFact: number[]): number {
    let res: number = mul(fact[n], invFact[r]);
    res = mul(res, invFact[n - r]);
    return res;
}

async function main() {
    const input: string[] = (await new Promise((resolve) => {
        process.stdin.on('data', (chunk) => resolve(chunk.toString()));
    })).split('\n');

    const n: number = parseInt(input[0].trim(), 10);
    const ls: string[] = [];
    let black: number = 0;
    let white: number = 0;
    let full: boolean = false;

    for (let i = 0; i < n; i++) {
        const line: string = input[i + 1].trim();
        ls.push(line);
        if (line[0] === 'W') white++;
        if (line[0] === 'B') black++;
        if (line[1] === 'W') white++;
        if (line[1] === 'B') black++;
        if (line[0] !== '?' && line[0] === line[1]) full = true;
    }

    if (black > n || white > n) {
        console.log(0);
        return;
    }

    const fact: number[] = new Array(2 * n + 1).fill(1);
    const invFact: number[] = new Array(2 * n + 1).fill(1);

    for (let i = 1; i <= 2 * n; i++) {
        fact[i] = mul(fact[i - 1], i);
        invFact[i] = modInverse(fact[i]);
    }

    const empty: number = 2 * n - black - white;
    let ans: number = nCr(empty, n - black, fact, invFact);

    if (full) {
        console.log(ans);
        return;
    }

    let invalid: number = 1;
    let wb: boolean = true;
    let bw: boolean = true;

    for (const line of ls) {
        if (line[0] === '?' && line[1] === '?') invalid = mul(invalid, 2);
        if (line[0] === 'B' || line[1] === 'W') wb = false;
        if (line[0] === 'W' || line[1] === 'B') bw = false;
    }

    if (wb) invalid = (MOD + invalid - 1) % MOD;
    if (bw) invalid = (MOD + invalid - 1) % MOD;

    ans = (ans - invalid + MOD) % MOD;
    console.log(ans);
}

