	fmt.Fscanf(scanner, "%d\n", &t)

	for tt := 0; tt < t; tt++ {
		scanner.Scan()
		scanner.Scan()
		nm := strings.Fields(scanner.Text())
		n, _ := strconv.Atoi(nm[0])
		m, _ := strconv.Atoi(nm[1])

		d := make([][]int, n)
		for i := range d {
			d[i] = make([]int, m)
			scanner.Scan()
			line := scanner.Text()
			for j := range line {
				switch line[j] {
				case 'R':
					d[i][j] = -1
				case 'U':
					d[i][j] = -2
				case 'L':
					d[i][j] = -3
				default:
					d[i][j] = -4
				}
			}
		}

		r := 0
		posI, posJ := 0, 0

		for i := 0; i < n; i++ {
			for j := 0; j < m; j++ {
				a, b := i, j
				p := d[i][j]
				c := 0
				st := make([][2]int, 0)

				for p < 0 {
					d[a][b] = 0
					st = append(st, [2]int{a, b})
					switch p {
					case -1:
						b++
					case -2:
						a--
					case -3:
						b--
					default:
						a++
					}
					c++
					if a >= 0 && a < n && b >= 0 && b < m {
						p = d[a][b]
					} else {
						for ii := 0; ii < len(st); ii++ {
							d[st[ii][0]][st[ii][1]] = c - ii
						}
						p = -1
						break
					}
				}

				if p == 0 {
					jj := 0
					flag := false
					for ii := 0; ii < len(st); ii++ {
						if flag {
							d[st[ii][0]][st[ii][1]] = c - jj
						} else {
							d[st[ii][0]][st[ii][1]] = c - ii
						}
						if st[ii][0] == a && st[ii][1] == b {
							flag = true
							jj = ii
						}
					}
				}

				if p > 0 {
					for ii := 0; ii < len(st); ii++ {
						d[st[ii][0]][st[ii][1]] = p + c - ii
					}
				}

				if d[i][j] > r {
					r = d[i][j]
					posI, posJ = i, j
				}
			}
		}

		fmt.Printf("%d %d %d\n", posI+1, posJ+1, r)
	}
}

