const mod = 1_000_000_007
const INF = 1 << 60

type dsu struct {
	parent []int
}

func newDsu(n int) *dsu {
	d := &dsu{parent: make([]int, n+1)}
	for i := 1; i <= n; i++ {
		d.parent[i] = i
	}
	return d
}

func (d *dsu) findParent(node int) int {
	if node == d.parent[node] {
		return node
	}
	d.parent[node] = d.findParent(d.parent[node])
	return d.parent[node]
}

func (d *dsu) union(u, v int) bool {
	uParent := d.findParent(u)
	vParent := d.findParent(v)

	if uParent != vParent {
		d.parent[vParent] = uParent
		return true
	}
	return false
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var n, m1, m2 int
	fmt.Fscanf(reader, "%d %d %d\n", &n, &m1, &m2)

	d1 := newDsu(n)
	d2 := newDsu(n)

	flag := 0

	for i := 0; i < m1; i++ {
		var u, v int
		fmt.Fscanf(reader, "%d %d\n", &u, &v)
		if !d1.union(u, v) {
			flag = 1
		}
	}

	for i := 0; i < m2; i++ {
		var u, v int
		fmt.Fscanf(reader, "%d %d\n", &u, &v)
		if !d2.union(u, v) {
			flag = 1
		}
	}

	if flag != 0 {
		fmt.Fprintln(writer, "0")
		return
	}

	var v [][2]int

	for i := 1; i <= n; i++ {
		for j := i + 1; j <= n; j++ {
			y := d1.findParent(j)
			y1 := d1.findParent(y)
			x := d2.findParent(j)
			x1 := d2.findParent(x)

			if !d1.union(i, j) {
				d1.parent[y] = y1
			} else if !d2.union(i, j) {
				d2.parent[x] = x1
				d1.parent[y] = y1
			} else {
				d1.union(i, j)
				d2.union(i, j)
				v = append(v, [2]int{i, j})
			}
		}
	}

	fmt.Fprintln(writer, len(v))
	for _, pair := range v {
		fmt.Fprintf(writer, "%d %d\n", pair[0], pair[1])
	}
}

