const BUFSIZE = 8192

type FastIO struct {
	buffer []byte
	pos    int
	end    int
}

func NewFastIO() *FastIO {
	return &FastIO{buffer: make([]byte, BUFSIZE), pos: 0, end: 0}
}

func (f *FastIO) Read() error {
	for {
		n, err := os.Stdin.Read(f.buffer[f.end:])
		if n == 0 || err != nil {
			break
		}
		f.end += n
	}
	return nil
}

func (f *FastIO) ReadLine() (string, error) {
	var result []byte
	for f.pos < f.end || f.Read() == nil {
		for f.pos < f.end && f.buffer[f.pos] != '\n' {
			result = append(result, f.buffer[f.pos])
			f.pos++
		}
		if f.pos < f.end {
			f.pos++
			break
		}
	}
	return string(result), nil
}

func (f *FastIO) IsEmpty() bool {
	return f.pos >= f.end
}

