	}

	p := make([][2]int, n)
	for i := 0; i < n; i++ {
		if scanner.Scan() {
			line := strings.Fields(scanner.Text())
			x, _ := strconv.Atoi(line[0])
			y, _ := strconv.Atoi(line[1])
			p[i] = [2]int{x, y}
		}
	}

	ans := 0
	cnt := 0
	r := make([][]int, n)
	for i := range r {
		r[i] = make([]int, n)
	}
	q := make([]int, n)

	for i := 0; i < n; i++ {
		for j := i + 1; j < n; j++ {
			dx := int(math.Abs(float64(p[i][0] - p[j][0])))
			dy := int(math.Abs(float64(p[i][1] - p[j][1])))
			if gcd(dx, dy)%4 == 0 {
				cnt++
				r[i][j] = 1
				q[i]++
				ans += n - 2
			}
		}
	}

	for i := 0; i < n; i++ {
		for j := 1; j < n; j++ {
			if r[i][j] == 1 {
				ans -= q[j] * 2
			}
		}
	}

	fmt.Println(ans)
}

func gcd(a, b int) int {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

