public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int t = Integer.parseInt(br.readLine());
        while (t-- > 0) {
            String[] parts = br.readLine().split(" ");
            int n = Integer.parseInt(parts[0]);
            int s = Integer.parseInt(parts[1]);
            System.out.println(s / ((n + 2) / 2));
        }
    }

    public static List<Integer> nextLargerElement(int[] arr, boolean f) {
        Stack<Integer> stack = new Stack<>();
        int[] ans = new int[arr.length];
        Arrays.fill(ans, -1);
        for (int i = 0; i < arr.length; i++) {
            while (!stack.isEmpty() && arr[stack.peek()] < arr[i]) {
                stack.pop();
            }
            if (!stack.isEmpty()) {
                ans[i] = stack.peek();
            }
            stack.push(i);
        }
        if (f) {
            for (int i = 0; i < arr.length; i++) {
                if (ans[i] != -1) {
                    ans[i] = arr.length - 1 - ans[i];
                }
            }
        }
        return Arrays.stream(ans).boxed().toList();
    }

    public static int dfs(List<List<Integer>> adj, int i, Integer p, int ans) {
        boolean f = true;
        int a1 = 0;
        for (int j : adj.get(i)) {
            if (!Objects.equals(j, p)) {
                a1 += dfs(adj, j, i, ans + 1);
                f = false;
            }
        }
        if (f) {
            a1 += (long) ans * (ans - 1) / 2; // Use long to prevent overflow
        }
        return a1;
    }
}

