            int[][] d = new int[n][m];
            for (int i = 0; i < n; i++) {
                String line = scanner.nextLine();
                for (int j = 0; j < m; j++) {
                    char c = line.charAt(j);
                    switch (c) {
                        case 'R':
                            d[i][j] = -1;
                            break;
                        case 'U':
                            d[i][j] = -2;
                            break;
                        case 'L':
                            d[i][j] = -3;
                            break;
                        default:
                            d[i][j] = -4;
                    }
                }
            }

            int r = 0;
            int posX = 0, posY = 0;

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    int a = i, b = j;
                    int p = d[a][b];
                    int c = 0;
                    List<int[]> st = new ArrayList<>();

                    while (p < 0) {
                        d[a][b] = 0;
                        st.add(new int[]{a, b});
                        if (p == -1) b++;
                        else if (p == -2) a--;
                        else if (p == -3) b--;
                        else a++;
                        c++;
                        if (a >= 0 && a < n && b >= 0 && b < m) {
                            p = d[a][b];
                        } else {
                            for (int ii = 0; ii < st.size(); ii++) {
                                int[] pos = st.get(ii);
                                d[pos[0]][pos[1]] = c - ii;
                            }
                            p = -1;
                            break;
                        }
                    }

                    if (p == 0) {
                        boolean flag = false;
                        int jj = 0;
                        for (int ii = 0; ii < st.size(); ii++) {
                            int[] pos = st.get(ii);
                            d[pos[0]][pos[1]] = flag ? c - jj : c - ii;
                            if (pos[0] == a && pos[1] == b) {
                                flag = true;
                                jj = ii;
                            }
                        }
                    }

                    if (p > 0) {
                        for (int ii = 0; ii < st.size(); ii++) {
                            int[] pos = st.get(ii);
                            d[pos[0]][pos[1]] = p + c - ii;
                        }
                    }

                    if (d[i][j] > r) {
                        r = d[i][j];
                        posX = i;
                        posY = j;
                    }
                }
            }

            System.out.println((posX + 1) + " " + (posY + 1) + " " + r);
        }
    }
