import java.io.*;
import java.util.*;

public class Main {
    private static final long MOD = 998244353;

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(reader.readLine());
        List<String> ls = new ArrayList<>();
        int black = 0;
        int white = 0;
        boolean full = false;
        for (int i = 0; i < n; i++) {
            String line = reader.readLine();
            ls.add(line);
            if (line.charAt(0) == 'W') white++;
            if (line.charAt(0) == 'B') black++;
            if (line.charAt(1) == 'W') white++;
            if (line.charAt(1) == 'B') black++;
            if (line.charAt(0) != '?' && line.charAt(0) == line.charAt(1)) full = true;
        }
        if (black > n || white > n) {
            System.out.println("0");
            return;
        }
        long[] fact = new long[2 * n + 1];
        long[] invFact = new long[2 * n + 1];
        fact[0] = 1;
        invFact[0] = 1;
        for (int i = 1; i <= 2 * n; i++) {
            fact[i] = mul(fact[i - 1], i);
            invFact[i] = modInverse(fact[i]);
        }
        int empty = 2 * n - black - white;
        long ans = nCr(empty, n - black, fact, invFact);
        if (full) {
            System.out.println(ans);
            return;
        }
        long invalid = 1;
        boolean wb = true;
        boolean bw = true;
        for (String line : ls) {
            if (line.charAt(0) == '?' && line.charAt(1) == '?') invalid = mul(invalid, 2);
            if (line.charAt(0) == 'B' || line.charAt(1) == 'W') wb = false;
            if (line.charAt(0) == 'W' || line.charAt(1) == 'B') bw = false;
        }
        if (wb) invalid--;
        if (bw) invalid--;
        ans -= invalid;
        System.out.println(ans);
    }

    private static long binPow(long a, long b) {
        long res = 1;
        while (b > 0) {
            a %= MOD;
            if ((b & 1) == 1) res = mul(res, a);
            b >>= 1;
            a = mul(a, a);
        }
        return res;
    }

    private static long modInverse(long a) {
        return binPow(a, MOD - 2);
    }

    private static long mul(long a, long b) {
        return (a * b) % MOD;
    }

    private static long nCr(int n, int r, long[] fact, long[] invFact) {
        long res = mul(fact[n], invFact[r]);
        res = mul(res, invFact[n - r]);
        return res;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    private static final int BUFSIZE = 8192;
    private static byte[] buffer = new byte[BUFSIZE];
    private static int bufferSize = 0;
    private static int bufferIndex = 0;

    public static void main(String[] args) throws IOException {
        FastIO io = new FastIO();
        int t = inp(io);
        while (t-- > 0) {
            int n = inp(io);
            List<Integer> l = inlt(io, n);
            int s = l.get(0);
            for (int i = 1; i < n; i++) {
                s &= l.get(i);
            }
            print(s + "\n");
        }
    }

    private static class FastIO extends PrintWriter {
        public FastIO() throws IOException {
            super(new OutputStreamWriter(System.out));
        }

        public String readLine() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            while ((c = System.in.read()) != -1 && c != '\n' && c != '\r') {
                sb.append((char) c);
            }
            return sb.toString().trim();
        }

        public String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            while ((c = read()) <= 32);
            do {
                sb.append((char) c);
            } while ((c = read()) > 32);
            return sb.toString().trim();
        }
    }

    private static int inp(FastIO io) throws IOException {
        return Integer.parseInt(io.next());
    }

    private static String inps(FastIO io) throws IOException {
        return io.readLine();
    }

    private static List<Integer> inlt(FastIO io, int n) throws IOException {
        List<Integer> list = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            list.add(Integer.parseInt(io.next()));
        }
        return list;
    }

    private static List<Character> insr(FastIO io) throws IOException {
        List<Character> list = new ArrayList<>();
        String s = io.readLine();
        for (char c : s.toCharArray()) {
            list.add(c);
        }
        return list;
    }

    private static List<Integer> invr(FastIO io) throws IOException {
        List<Integer> list = new ArrayList<>();
        String[] parts = io.readLine().split(" ");
        for (String part : parts) {
            list.add(Integer.parseInt(part));
        }
        return list;
    }

    private static void print(String... args) {
        System.out.print(String.join("", args));
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = Integer.parseInt(scanner.nextLine().trim());
        int[][] p = new int[n][2];

        for (int i = 0; i < n; ++i) {
            String[] coords = scanner.nextLine().trim().split("\\s+");
            p[i][0] = Integer.parseInt(coords[0]);
            p[i][1] = Integer.parseInt(coords[1]);
        }

        int ans = 0;
        int cnt = 0;
        int[][] r = new int[n][n];
        int[] q = new int[n];

        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                int dx = Math.abs(p[i][0] - p[j][0]);
                int dy = Math.abs(p[i][1] - p[j][1]);
                if (gcd(dx, dy) % 4 == 0) {
                    cnt++;
                    r[i][j] = 1;
                    q[i]++;
                    ans += n - 2;
                }
            }
        }

        for (int i = 0; i < n; ++i) {
            for (int j = 1; j < n; ++j) {
                if (r[i][j] == 1) {
                    ans -= q[j] * 2;
                }
            }
        }

        System.out.println(ans);
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int t = b;
            b = a % b;
            a = t;
        }
        return a;
    }
}

