        {
            reader.ReadLine();
            string[] nm = reader.ReadLine().Split(' ');
            int n = int.Parse(nm[0]);
            int m = int.Parse(nm[1]);

            int[,] d = new int[n, m];
            for (int i = 0; i < n; i++)
            {
                string line = reader.ReadLine();
                for (int j = 0; j < m; j++)
                {
                    char c = line[j];
                    switch (c)
                    {
                        case 'R': d[i, j] = -1; break;
                        case 'U': d[i, j] = -2; break;
                        case 'L': d[i, j] = -3; break;
                        default: d[i, j] = -4; break;
                    }
                }
            }

            int r = 0;
            int posI = 0, posJ = 0;

            for (int i = 0; i < n; i++)
            {
                for (int j = 0; j < m; j++)
                {
                    int a = i, b = j;
                    int p = d[a, b];
                    int c = 0;
                    Stack<(int, int)> st = new Stack<(int, int)>();

                    while (p < 0)
                    {
                        d[a, b] = 0;
                        st.Push((a, b));
                        if (p == -1) b++;
                        else if (p == -2) a--;
                        else if (p == -3) b--;
                        else a++;

                        c++;
                        if (a >= 0 && a < n && b >= 0 && b < m)
                            p = d[a, b];
                        else
                        {
                            int ii = 0;
                            foreach (var item in st)
                            {
                                d[item.Item1, item.Item2] = c - ii++;
                            }
                            p = -1;
                            break;
                        }
                    }

                    if (p == 0)
                    {
                        bool flag = false;
                        int jj = 0;
                        int ii = 0;
                        foreach (var item in st)
                        {
                            d[item.Item1, item.Item2] = flag ? c - jj++ : c - ii++;
                            if (item.Item1 == a && item.Item2 == b)
                            {
                                flag = true;
                                jj = ii;
                            }
                        }
                    }

                    if (p > 0)
                    {
                        int ii = 0;
                        foreach (var item in st)
                        {
                            d[item.Item1, item.Item2] = p + c - ii++;
                        }
                    }

                    if (d[i, j] > r)
                    {
                        r = d[i, j];
                        posI = i;
                        posJ = j;
                    }
                }
            }

            Console.WriteLine($"{posI + 1} {posJ + 1} {r}");
        }
    }
}

