using System;
using System.Collections.Generic;

class Program
{
    const int MOD = 1_000_000_007;
    const long INF = 1L << 60;

    class Dsu
    {
        public List<int> parent;

        public Dsu(int n)
        {
            parent = new List<int>(new int[n + 1]);
            for (int i = 1; i <= n; i++)
            {
                parent[i] = i;
            }
        }

        public int FindParent(int node)
        {
            if (node == parent[node])
            {
                return node;
            }
            parent[node] = FindParent(parent[node]);
            return parent[node];
        }

        public int Union(int u, int v)
        {
            int uParent = FindParent(u);
            int vParent = FindParent(v);

            if (uParent != vParent)
            {
                parent[vParent] = uParent;
                return 0;
            }
            else
            {
                return -1;
            }
        }

        public void CheckComponent(int u, int w)
        {
            if (FindParent(u) != FindParent(w))
            {
                Console.WriteLine("Both belongs to different components");
            }
            else
            {
                Console.WriteLine("same component");
            }
        }
    }

    static void Main()
    {
        var input = Console.In.ReadToEnd().Split(new char[] { '\n', ' ', '\t' }, StringSplitOptions.RemoveEmptyEntries);
        int index = 0;

        int n = int.Parse(input[index++]);
        int m1 = int.Parse(input[index++]);
        int m2 = int.Parse(input[index++]);

        Dsu d1 = new Dsu(n);
        Dsu d2 = new Dsu(n);

        int flag = 0;
        for (int i = 0; i < m1; i++)
        {
            int u = int.Parse(input[index++]);
            int v = int.Parse(input[index++]);
            if (d1.Union(u, v) == -1)
            {
                flag = 1;
            }
        }

        for (int i = 0; i < m2; i++)
        {
            int u = int.Parse(input[index++]);
            int v = int.Parse(input[index++]);
            if (d2.Union(u, v) == -1)
            {
                flag = 1;
            }
        }

        if (flag != 0)
        {
            Console.WriteLine(0);
            return;
        }

        List<(int, int)> edges = new List<(int, int)>();
        for (int i = 1; i <= n; i++)
        {
            for (int j = i + 1; j <= n; j++)
            {
                int y = d1.FindParent(j);
                int y1 = d1.FindParent(y);
                int x = d2.FindParent(j);
                int x1 = d2.FindParent(x);

                if (d1.Union(i, j) == -1)
                {
                    d1.parent[y] = y1;
                }
                else if (d2.Union(i, j) == -1)
                {
                    d2.parent[x] = x1;
                    d1.parent[y] = y1;
                }
                else
                {
                    d1.Union(i, j);
                    d2.Union(i, j);
                    edges.Add((i, j));
                }
            }
        }

        Console.WriteLine(edges.Count);
        foreach (var edge in edges)
        {
            Console.WriteLine($"{edge.Item1} {edge.Item2}");
        }
    }
}

