using System;
using System.Collections.Generic;

class Program
{
    const long MOD = 998244353;

    static long BinPow(long a, long b)
    {
        long res = 1;
        while (b > 0)
        {
            a %= MOD;
            if ((b & 1) == 1)
                res = (res * a) % MOD;
            b >>= 1;
            a = (a * a) % MOD;
        }
        return res;
    }

    static long ModInverse(long a)
    {
        return BinPow(a, MOD - 2);
    }

    static long Mul(long a, long b)
    {
        return (a * b) % MOD;
    }

    static long NCr(int n, int r, List<long> fact, List<long> invFact)
    {
        long res = Mul(fact[n], invFact[r]);
        res = Mul(res, invFact[n - r]);
        return res;
    }

    static void Main()
    {
        var reader = Console.In;
        var writer = Console.Out;

        int n = int.Parse(reader.ReadLine());
        List<string> ls = new List<string>();
        int black = 0;
        int white = 0;
        bool full = false;

        for (int i = 0; i < n; i++)
        {
            string s = reader.ReadLine();
            ls.Add(s);
            if (s[0] == 'W') white++;
            if (s[0] == 'B') black++;
            if (s[1] == 'W') white++;
            if (s[1] == 'B') black++;
            if (s[0] != '?' && s[0] == s[1]) full = true;
        }

        if (black > n || white > n)
        {
            writer.WriteLine(0);
            return;
        }

        List<long> fact = new List<long>(new long[2 * n + 1]);
        List<long> invFact = new List<long>(new long[2 * n + 1]);

        fact[0] = 1;
        invFact[0] = 1;

        for (int i = 1; i <= 2 * n; i++)
        {
            fact[i] = Mul(fact[i - 1], i);
            invFact[i] = ModInverse(fact[i]);
        }

        int empty = 2 * n - black - white;
        long ans = NCr(empty, n - black, fact, invFact);

        if (full)
        {
            writer.WriteLine(ans);
            return;
        }

        long invalid = 1;
        bool wb = true;
        bool bw = true;

        foreach (var s in ls)
        {
            if (s[0] == '?' && s[1] == '?') invalid = Mul(invalid, 2);
            if (s[0] == 'B' || s[1] == 'W') wb = false;
            if (s[0] == 'W' || s[1] == 'B') bw = false;
        }

        if (wb) invalid--;
        if (bw) invalid--;

        ans -= invalid;
        writer.WriteLine(ans);
    }
}

using System;
using System.Collections.Generic;
using System.IO;

class Program
{
    private const int BUFSIZE = 8192;
    private static byte[] buffer = new byte[BUFSIZE];
    private static int pos = 0;
    private static int end = 0;

    public static void Main(string[] args)
    {
        var reader = Console.OpenStandardInput();
        var writer = Console.OpenStandardOutput();

        try
        {
            int t = Inp(reader);
            for (int i = 0; i < t; i++)
            {
                int n = Inp(reader);
                List<int> l = Inlt(reader);
                int s = l[0];
                for (int j = 1; j < n; j++)
                {
                    s &= l[j];
                }
                Print(writer, new[] { s.ToString() }, " ", "\n");
            }
        }
        finally
        {
            reader.Close();
            writer.Close();
        }
    }

    private static void Read(Stream stream)
    {
        end = stream.Read(buffer, 0, BUFSIZE);
        pos = 0;
    }

    private static string ReadLine(Stream stream)
    {
        var result = new List<byte>();
        while (true)
        {
            if (pos >= end)
            {
                Read(stream);
                if (end == 0) break;
            }
            while (pos < end && buffer[pos] != '\n')
            {
                result.Add(buffer[pos++]);
            }
            if (pos < end)
            {
                pos++;
                break;
            }
        }
        return System.Text.Encoding.UTF8.GetString(result.ToArray());
    }

    private static bool IsEmpty()
    {
        return pos >= end;
    }

    public static void Print(Stream stream, string[] args, string sep, string end)
    {
        using (var writer = new StreamWriter(stream, System.Text.Encoding.UTF8, BUFSIZE, true))
        {
            for (int i = 0; i < args.Length; i++)
            {
                if (i > 0) writer.Write(sep);
                writer.Write(args[i]);
            }
            writer.WriteLine(end);
        }
    }

    public static int Inp(Stream stream)
    {
        return int.Parse(ReadLine(stream).Trim());
    }

    public static string Inps(Stream stream)
    {
        return ReadLine(stream).Trim();
    }

    public static List<int> Inlt(Stream stream)
    {
        return Array.ConvertAll(ReadLine(stream).Split(' '), int.Parse).ToList();
    }

    public static List<char> Insr(Stream stream)
    {
        return ReadLine(stream).Trim().ToCharArray().ToList();
    }

    public static List<int> Invr(Stream stream)
    {
        return Array.ConvertAll(ReadLine(stream).Split(' '), int.Parse).ToList();
    }
}

