    while (t--) {
        std::string line;
        std::getline(std::cin, line); // Consume the empty line

        int n, m;
        std::cin >> n >> m;
        std::vector<std::vector<int>> d(n, std::vector<int>(m, -1));

        for (int i = 0; i < n; ++i) {
            std::getline(std::cin, line);
            for (int j = 0; j < m; ++j) {
                char c = line[j];
                if (c == 'R') d[i][j] = -1;
                else if (c == 'U') d[i][j] = -2;
                else if (c == 'L') d[i][j] = -3;
            }
        }

        int r = 0;
        int pos_i = 0, pos_j = 0;

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                int a = i, b = j;
                int p = d[a][b];
                int c = 0;
                std::vector<std::pair<int, int>> st;

                while (p < 0) {
                    d[a][b] = 0;
                    st.emplace_back(a, b);
                    if (p == -1) ++b;
                    else if (p == -2) --a;
                    else if (p == -3) --b;
                    else ++a;
                    ++c;
                    if (a >= 0 && a < n && b >= 0 && b < m) {
                        p = d[a][b];
                    } else {
                        for (size_t ii = 0; ii < st.size(); ++ii) {
                            auto [x, y] = st[ii];
                            d[x][y] = c - static_cast<int>(ii);
                        }
                        p = -1;
                        break;
                    }
                }

                if (p == 0) {
                    int jj = 0;
                    bool flag = false;
                    for (size_t ii = 0; ii < st.size(); ++ii) {
                        auto [x, y] = st[ii];
                        d[x][y] = flag ? c - jj : c - static_cast<int>(ii);
                        if (x == a && y == b) {
                            flag = true;
                            jj = static_cast<int>(ii);
                        }
                    }
                }

                if (p > 0) {
                    for (size_t ii = 0; ii < st.size(); ++ii) {
                        auto [x, y] = st[ii];
                        d[x][y] = p + c - static_cast<int>(ii);
                    }
                }

                if (d[i][j] > r) {
                    r = d[i][j];
                    pos_i = i;
                    pos_j = j;
                }
            }
        }

        std::cout << pos_i + 1 << " " << pos_j + 1 << " " << r << "\n";
    }

    return 0;
}

