const long long MOD = 998244353;

long long bin_pow(long long a, long long b) {
    long long res = 1;
    while (b > 0) {
        a %= MOD;
        if (b & 1) {
            res = (res * a) % MOD;
        }
        b >>= 1;
        a = (a * a) % MOD;
    }
    return res;
}

long long mod_inverse(long long a) {
    return bin_pow(a, MOD - 2);
}

long long mul(long long a, long long b) {
    return (a * b) % MOD;
}

long long n_cr(int n, int r, const std::vector<long long>& fact, const std::vector<long long>& inv_fact) {
    long long res = mul(fact[n], inv_fact[r]);
    res = mul(res, inv_fact[n - r]);
    return res;
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;

    std::vector<std::string> ls(n);
    int black = 0, white = 0;
    bool full = false;

    for (int i = 0; i < n; ++i) {
        std::cin >> ls[i];
        if (ls[i][0] == 'W') ++white;
        if (ls[i][0] == 'B') ++black;
        if (ls[i][1] == 'W') ++white;
        if (ls[i][1] == 'B') ++black;
        if (ls[i][0] != '?' && ls[i][0] == ls[i][1]) full = true;
    }

    if (black > n || white > n) {
        std::cout << "0\n";
        return 0;
    }

    std::vector<long long> fact(2 * n + 1), inv_fact(2 * n + 1);
    fact[0] = inv_fact[0] = 1;

    for (int i = 1; i <= 2 * n; ++i) {
        fact[i] = mul(fact[i - 1], i);
        inv_fact[i] = mod_inverse(fact[i]);
    }

    int empty = 2 * n - black - white;
    long long ans = n_cr(empty, n - black, fact, inv_fact);

    if (full) {
        std::cout << ans << "\n";
        return 0;
    }

    long long invalid = 1;
    bool wb = true, bw = true;

    for (const auto& line : ls) {
        if (line[0] == '?' && line[1] == '?') {
            invalid = mul(invalid, 2);
        }
        if (line[0] == 'B' || line[1] == 'W') wb = false;
        if (line[0] == 'W' || line[1] == 'B') bw = false;
    }

    if (wb) --invalid;
    if (bw) --invalid;

    ans -= invalid;
    std::cout << ans << "\n";

    return 0;
}

