const int BUFSIZE = 8192;

class FastIO {
private:
    char buffer[BUFSIZE];
    int pos, end;
public:
    FastIO() : pos(0), end(0) {}

    bool read() {
        end = std::cin.rdbuf()->sgetn(buffer, BUFSIZE);
        pos = 0;
        return end > 0;
    }

    std::string readline() {
        std::string result;
        while (pos < end || read()) {
            while (pos < end && buffer[pos] != '\n') {
                result += buffer[pos++];
            }
            if (pos < end) {
                ++pos; // Skip the newline character
                break;
            }
        }
        return result;
    }

    bool is_empty() const {
        return pos >= end;
    }
};

