func nextLargerElement(_ arr: [Int], _ n: Int, _ f: Bool) -> [Int] {
    var s: [Int] = []
    var ans = Array(repeating: -1, count: n)
    for i in 0..<n {
        while !s.isEmpty && arr[s.last!] < arr[i] {
            s.removeLast()
        }
        if !s.isEmpty {
            ans[i] = s.last!
        }
        s.append(i)
    }
    if f {
        for i in 0..<n {
            if ans[i] != -1 {
                ans[i] = n - 1 - ans[i]
            }
        }
    }
    return ans
}

func dfs(_ i: Int, _ adj: [[Int]], _ p: Int?, _ ans: Int) -> Int {
    var f = true
    var a1 = 0
    for j in adj[i] {
        if j != p {
            a1 += dfs(j, adj, i, ans + 1)
            f = false
        }
    }
    if f {
        a1 += ans * (ans - 1) / 2
    }
    return a1
}

