func binPow(_ a: Int, _ b: Int) -> Int {
    var res = 1
    var a = a % mod
    var b = b

    while b > 0 {
        if b & 1 == 1 {
            res = (res * a) % mod
        }
        b >>= 1
        a = (a * a) % mod
    }

    return res
}

func modInverse(_ a: Int) -> Int {
    return binPow(a, mod - 2)
}

func mul(_ a: Int, _ b: Int) -> Int {
    return (a * b) % mod
