import Foundation

class FastIO {
    private var buffer: Data
    private let bufferSize = 8192
    private var position = 0

    init() {
        self.buffer = Data(capacity: bufferSize)
    }

    func read() throws -> String {
        var result = ""
        repeat {
            let data = try FileHandle.standardInput.read(upToCount: bufferSize)
            if let data = data {
                buffer.append(data)
            }
            if let range = buffer.range(of: "\n".data(using: .utf8)!, options: [], in: buffer.startIndex..<buffer.endIndex) {
                result += String(data: buffer[buffer.startIndex..<range.lowerBound], encoding: .utf8)!
                position = range.upperBound
                buffer.removeSubrange(buffer.startIndex..<range.upperBound)
                break
            }
        } while !buffer.isEmpty
        return result.trimmingCharacters(in: .whitespacesAndNewlines)
    }

    func readline() throws -> String {
        var line = ""
        while true {
            if position < buffer.count {
                let end = buffer.firstIndex(of: 10, in: buffer.startIndex..<buffer.endIndex) ?? buffer.endIndex
                line += String(data: buffer[position..<end], encoding: .utf8)!
                position = end == buffer.endIndex ? 0 : end + 1
                if end != buffer.endIndex {
                    break
                }
            } else {
                position = 0
                let data = try FileHandle.standardInput.read(upToCount: bufferSize)
                if let data = data {
                    buffer = data
                } else {
                    break
                }
            }
        }
        return line
    }

    func is_empty() -> Bool {
        return buffer.isEmpty
    }
}

