function nextLargerElement(arr: number[], n: number, f: boolean): number[] {
    const s: number[] = [];
    const ans: number[] = new Array(n).fill(-1);
    for (let i = 0; i < n; i++) {
        while (s.length > 0 && arr[s[s.length - 1]] < arr[i]) {
            s.pop();
        }
        if (s.length > 0) {
            ans[i] = s[s.length - 1];
        }
        s.push(i);
    }
    if (f) {
        for (let i = 0; i < n; i++) {
            if (ans[i] !== -1) {
                ans[i] = n - 1 - ans[i];
            }
        }
    }
    return ans;
}

