    for (const j of adj[i]) {
        if (j !== p) {
            a1 += dfs(j, adj, i, ans + 1);
            f = false;
        }
    }
    if (f) {
        a1 += Math.floor((ans * (ans - 1)) / 2);
    }
    return a1;
}

