class Dsu {
    private parent: number[];

    constructor(n: number) {
        this.parent = new Array(n + 1).fill(0);
    }

    public makeSet(): void {
        for (let i = 1; i <= this.parent.length - 1; i++) {
            this.parent[i] = i;
        }
    }

    private findParent(node: number): number {
        if (node === this.parent[node]) {
            return node;
        }
        this.parent[node] = this.findParent(this.parent[node]);
        return this.parent[node];
    }

    public union(u: number, v: number): number {
        const uParent = this.findParent(u);
        const vParent = this.findParent(v);

        if (uParent !== vParent) {
            this.parent[vParent] = uParent;
            return 0;
        } else {
            return -1;
        }
    }

    public checkComponent(u: number, v: number): void {
        if (this.findParent(u) !== this.findParent(v)) {
            console.log("Both belongs to different components");
        } else {
            console.log("same component");
        }
    }
}

