import (
	"bufio"
	"fmt"
	"math/big"
	"os"
)

const mod = 998244353

func egcd(a, b int64) (g, x, y int64) {
	if a == 0 {
		return b, 0, 1
	}
	g, y, x = egcd(b%a, a)
	return g, x-(b/a)*y, y
}

func modinv(a, m int64) int64 {
	g, x, _ := egcd(a, m)
	if g != 1 {
		panic("modular inverse does not exist")
	}
	return (x%m + m) % m
}

func choose(n, k, p int64) int64 {
	if k == 0 || k == n {
		return 1
	}
	x := big.NewInt(1)
	for y := n; y > n-k; y-- {
		x.Mul(x, big.NewInt(y)).Mod(x, big.NewInt(p))
	}
	d := big.NewInt(1)
	for i := int64(2); i <= k; i++ {
		d.Mul(d, big.NewInt(i)).Mod(d, big.NewInt(p))
	}
	x.Mul(x, big.NewInt(modinv(d.Int64(), p))).Mod(x, big.NewInt(p))
	return x.Int64()
}

func solve() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	var n int
	fmt.Sscanf(scanner.Text(), "%d", &n)

	wbPoss := true
	bwPoss := true
	w := 0
	b := 0
	q := 0
	free := 0
	anyBadPoss := true

	for i := 0; i < n; i++ {
		scanner.Scan()
		s := scanner.Text()

		if s[0] == 'B' {
			b++
			wbPoss = false
		} else if s[0] == 'W' {
			w++
			bwPoss = false
		} else if s[0] == '?' {
			q++
		}

		if s[len(s)-1] == 'B' {
			b++
			bwPoss = false
		} else if s[len(s)-1] == 'W' {
			w++
			bwPoss = false
		} else if s[len(s)-1] == '?' {
			q++
		}

		if s == "??" {
			free++
		} else if s[0] == s[len(s)-1] {
			anyBadPoss = false
		}
	}

	wNeeded := n - b
	if wNeeded > q || wNeeded < 0 {
		fmt.Println(0)
		return
	}

	var numBadPoss int64
	if anyBadPoss {
		numBadPoss = big.NewInt(2).Exp(big.NewInt(2), big.NewInt(int64(free)), nil).Int64() % mod
		if bwPoss {
			numBadPoss--
		}
		if wbPoss {
			numBadPoss--
		}
	} else {
		numBadPoss = 0
	}

	fmt.Println((choose(int64(q), int64(wNeeded), mod)-numBadPoss+mod)%mod)
}

func main() {
	solve()
}

