package main

import (
	"bufio"
	"fmt"
	"os"
)

const N = 1e6 + 10

var (
	s [N]string
	d [N]int
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var n, m int
	fmt.Fscanf(reader, "%d %d\n", &n, &m)

	for i := 1; i <= n; i++ {
		s[i], _ = reader.ReadString('\n')
		s[i] = s[i][:len(s[i])-1] // Remove newline character
	}

	for i := 1; i <= m; i++ {
		for j := 2; j <= n; j++ {
			if len(s[j]) > i-1 && len(s[j-1]) > i &&
				s[j][i-1] == 'X' && s[j-1][i] == 'X' {
				d[i] = 1
				break
			}
		}
	}

	for i := 1; i <= m; i++ {
		d[i] += d[i-1]
	}

	var q int
	fmt.Fscanf(reader, "%d\n", &q)

	for i := 0; i < q; i++ {
		var l, r int
		fmt.Fscanf(reader, "%d %d\n", &l, &r)
		if d[r-1]-d[l-1] != 0 {
			fmt.Fprintln(writer, "NO")
		} else {
			fmt.Fprintln(writer, "YES")
		}
	}
}

