        Scanner scanner = new Scanner(System.in);
        int t = Integer.parseInt(scanner.nextLine());
        for (int testCase = 0; testCase < t; testCase++) {
            String[] input = scanner.nextLine().split(" ");
            int n = Integer.parseInt(input[0]);
            int m = Integer.parseInt(input[1]);
            int k = Integer.parseInt(input[2]);

            int bigTablesStartingNum = 0;
            int bigTablesCount = n % m;
            int bigTableSize = 1 + n / m;

            int smallTablesCount = m - n % m;
            int smallTableSize = n / m;
            int peopleAtBigTables = bigTableSize * bigTablesCount;

            int[] bigTableNums = new int[bigTableSize];
            int[] smallTableNums = new int[smallTableSize];

            for (int iteration = 0; iteration < k; iteration++) {
                int i = 0;
                for (int bt = 0; bt < bigTablesCount; bt++) {
                    for (int x = 0; x < bigTableSize; x++) {
                        bigTableNums[x] = (bigTablesStartingNum + i) % n + 1;
                        i++;
                    }
                    printTable(bigTableNums);
                }
                for (int st = 0; st < smallTablesCount; st++) {
                    for (int x = 0; x < smallTableSize; x++) {
                        smallTableNums[x] = (bigTablesStartingNum + i) % n + 1;
                        i++;
                    }
                    printTable(smallTableNums);
                }
                bigTablesStartingNum = (bigTablesStartingNum + peopleAtBigTables) % n;
            }
            System.out.println();
        }
        scanner.close();
    }

    private static void printTable(int[] nums) {
        StringBuilder sb = new StringBuilder();
        sb.append(nums.length);
        for (int num : nums) {
            sb.append(" ").append(num);
        }
        System.out.println(sb.toString());
    }
}

