class Program
{
    const int Mod = 998244353;

    static void Main()
    {
        var reader = new System.IO.StreamReader(Console.OpenStandardInput());
        var writer = new System.IO.StreamWriter(Console.OpenStandardOutput()) { AutoFlush = true };

        int t = int.Parse(reader.ReadLine());
        for (int _ = 0; _ < t; _++)
        {
            int n = int.Parse(reader.ReadLine());
            List<int> a = ReadIntArray(reader);
            Solve(n, a, writer);
        }
    }

    static void Solve(int n, List<int> a, System.IO.TextWriter writer)
    {
        int[] dp1 = new int[n + 2];
        int[] dp2 = new int[n + 2];
        dp1[0] = 1;

        foreach (int i in a)
        {
            dp1[i + 1] = (dp1[i + 1] * 2) % Mod;
            dp1[i + 1] = (dp1[i + 1] + dp1[i]) % Mod;
            if (i > 0)
            {
                dp2[i - 1] = (dp2[i - 1] * 2) % Mod;
                dp2[i - 1] = (dp2[i - 1] + dp1[i - 1]) % Mod;
            }
            dp2[i + 1] = (dp2[i + 1] * 2) % Mod;
        }

        int ans = 0;
        for (int i = 0; i < n + 2; i++)
        {
            ans = (ans + dp1[i] + dp2[i]) % Mod;
        }
        writer.WriteLine((ans - 1 + Mod) % Mod);
    }

    static List<int> ReadIntArray(System.IO.TextReader reader)
    {
        return Array.ConvertAll(reader.ReadLine().Split(' '), int.Parse).ToList();
    }
}

