class Program
{
    const int Mod = 998244353;

    static (int, int, int) Egcd(int a, int b)
    {
        if (a == 0)
            return (b, 0, 1);
        else
        {
            var result = Egcd(b % a, a);
            int g = result.Item1;
            int y = result.Item2;
            int x = result.Item3;
            return (g, x - (b / a) * y, y);
        }
    }

    static int Modinv(int a, int m)
    {
        var result = Egcd(a, m);
        int g = result.Item1;
        int x = result.Item2;
        if (g != 1)
            throw new InvalidOperationException("modular inverse does not exist");
        else
            return (x % m + m) % m;
    }

    static int Choose(int n, int k, int p)
    {
        if (k == 0 || k == n)
            return 1;
        long x = n;
        for (int y = n - 1; y > n - k; y--)
            x = (x * y) % p;
        long d = 1;
        for (int i = 2; i <= k; i++)
            d = (d * i) % p;
        return (int)((x * Modinv((int)d, p)) % p);
    }

    static void Solve()
    {
        int n = int.Parse(Console.ReadLine());
        bool wbPoss = true;
        bool bwPoss = true;
        int w = 0;
        int b = 0;
        int q = 0;
        int free = 0;
        bool anyBadPoss = true;

        for (int i = 0; i < n; i++)
        {
            string s = Console.ReadLine().Trim();
            if (s[0] == 'B')
            {
                b++;
                wbPoss = false;
            }
            else if (s[0] == 'W')
            {
                w++;
                bwPoss = false;
            }
            else if (s[0] == '?')
                q++;

            if (s[s.Length - 1] == 'B')
            {
                b++;
                bwPoss = false;
            }
            else if (s[s.Length - 1] == 'W')
            {
                w++;
                wbPoss = false;
            }
            else if (s[s.Length - 1] == '?')
                q++;

            if (s == "??" || s[0] != s[s.Length - 1])
                free++;
            else
                anyBadPoss = false;
        }

        int wNeeded = n - b;
        if (wNeeded > q || wNeeded < 0)
        {
            Console.WriteLine(0);
            return;
        }

        int numBadPoss;
        if (anyBadPoss)
            numBadPoss = (int)(((long)Math.Pow(2, free) % Mod) - (bwPoss ? 1 : 0) - (wbPoss ? 1 : 0) + Mod) % Mod;
        else
            numBadPoss = 0;

        Console.WriteLine((Choose(q, wNeeded, Mod) - numBadPoss + Mod) % Mod);
    }

    static void Main(string[] args)
    {
        Solve();
    }
}

