fn next_larger_element(arr: &[i32], n: usize, f: bool) -> Vec<i32> {
    let mut s = Vec::new();
    let mut ans = vec![-1; n];
    for i in 0..n {
        while !s.is_empty() && arr[*s.last().unwrap()] < arr[i] {
            s.pop();
        }
        if let Some(&last) = s.last() {
            ans[i] = last as i32;
        }
        s.push(i);
    }
    if f {
        for i in 0..n {
            if ans[i] != -1 {
                ans[i] = n as i32 - 1 - ans[i];
            }
        }
    }
    ans
}

fn dfs(i: usize, adj: &[Vec<usize>], p: usize, ans: i32) -> i32 {
    let mut f = true;
    let mut a1 = 0;
    for &j in &adj[i] {
        if j != p {
            a1 += dfs(j, adj, i, ans + 1);
            f = false;
        }
    }
    if f {
        a1 += ans * (ans - 1) / 2;
    }
    a1
}

