        let mut result = String::new();

        for _ in 0..t {
            let n: usize = lines.next().unwrap().parse().unwrap();
            let ar: Vec<i32> = lines.next().unwrap()
                .split_whitespace()
                .map(|s| s.parse().unwrap())
                .collect();

            let mut ans = i32::MAX;

            for j in 0..3 {
                for k in 0..3 {
                    let mut mod3 = [[0, i32::MAX]; 10];
                    mod3[0][0] = 1;
                    mod3[0][1] = 0;

                    for l in 0..=j {
                        for m in 0..=k {
                            let index = l + m * 2;
                            if index < 10 {
                                mod3[index][0] = 1;
                                mod3[index][1] = mod3[index][1].min(l as i32 + m as i32);
                            }
                        }
                    }

                    let mut mx = 0;

                    for &num in &ar {
                        let mod_val = num % 3;
                        let mut mn = i32::MAX;

                        for i in (mod_val..=num).step_by(3) {
                            if i < 10 && mod3[i as usize][0] == 1 {
                                mn = mn.min((num - i) / 3);
                            }
                        }

                        mx = mx.max(mn);
                    }

                    if mx != i32::MAX {
                        ans = ans.min(mx + j as i32 + k as i32);
                    }
                }
            }

            result.push_str(&format!("{}\n", ans));
        }

        result
    }
}

