                contains_minus_one = true;
                break;
            }
            if (ANS[i] > max_value) {
                max_value = ANS[i];
            }
        }

        if (contains_minus_one) {
            std::cout << -1 << std::endl;
        } else {
            std::cout << max_value << std::endl;
        }
    }

    return 0;
}

