                std::cin >> ar[i];
            }

            int ans = INT_MAX;

            for (int j = 0; j < 3; ++j) {
                for (int k = 0; k < 3; ++k) {
                    std::vector<std::vector<int>> mod3(10, std::vector<int>(2, 0));
                    mod3[0][0] = 1;
                    mod3[0][1] = 0;

                    for (int l = 0; l <= j; ++l) {
                        for (int m = 0; m <= k; ++m) {
                            int index = l + m * 2;
                            if (index < 10) {
                                mod3[index][0] = 1;
                                mod3[index][1] = std::min(l + m, mod3[index][1]);
                            }
                        }
                    }

                    int mx = 0;

                    for (int num : ar) {
                        int mod = num % 3;
                        int mn = INT_MAX;

                        for (int i = mod; i <= num; i += 3) {
                            if (i < 10 && mod3[i][0]) {
                                mn = std::min((num - i) / 3, mn);
                            }
                        }

                        mx = std::max(mx, mn);
                    }

                    if (mx != INT_MAX) {
                        ans = std::min(ans, mx + j + k);
                    }
                }
            }

            std::cout << ans << '\n';
        }
    }
